import os, json

def load_json(file_path):
    try:
        with open(file_path) as f:
            return json.load(f)
    except Exception as e:
        print(f"âš ï¸� Could not load {file_path}: {e}")
        return None


def detect_arc_test_file(base_path="/kaggle/input"):
    print("ğŸ”� Scanning input folders for ARC files...")
    candidate_files = []

    # --- Step 1: find likely JSONs ---
    for root, _, files in os.walk(base_path):
        for file in files:
            if file.endswith(".json"):
                full_path = os.path.join(root, file)
                if any(kw in file.lower() for kw in ["challenge", "test", "private"]):
                    candidate_files.append(full_path)

    # --- Step 2: prioritize ---
    candidate_files = sorted(candidate_files, key=lambda x: (
        "private" not in x.lower(),
        "test" not in x.lower(),
        "evaluation" in x.lower(),
        "train" in x.lower()
    ))

    # --- Step 3: verify structure ---
    for full_path in candidate_files:
        try:
            data = load_json(full_path)
            if not data:
                continue
            first_key = next(iter(data))
            if isinstance(data[first_key], dict) and "test" in data[first_key]:
                print(f"âœ… Found valid ARC test file: {full_path}")
                return data
        except Exception as e:
            print(f"âš ï¸� Skipped {full_path}: {e}")
            continue

    # --- Step 4: fallback ---
    fallback_path = os.path.join(base_path, "arc-prize-2025", "arc-agi_evaluation_challenges.json")
    if os.path.exists(fallback_path):
        return load_json(fallback_path)
    else:
        raise FileNotFoundError("â�Œ No valid test or evaluation ARC challenge JSON found.")


