# Flatten function to convert 2D grid to string
def flatten(grid):
    return ' | '.join([','.join(map(str, row)) for row in grid])

# Convert ARC JSON to DataFrame
def arc_json_to_dataframe(data):
    rows = []
    for task_id, content in data.items():
        for i, sample in enumerate(content.get("train", [])):
            rows.append({
                "task_id": task_id,
                "type": "train",
                "input number": i,
                "input": flatten(sample["input"]),
                "output": flatten(sample["output"])
            })
        for i, sample in enumerate(content.get("test", [])):
            rows.append({
                "task_id": task_id,
                "type": "test",
                "input number": i,
                "input": flatten(sample["input"]),
                "output": ""
            })
    return pd.DataFrame(rows)

# Convert training_solutions to DataFrame
def solutions_to_dataframe(data):
    rows = []
    for task_id, solutions in data.items():
        for i, output in enumerate(solutions):
            rows.append({
                "task_id": task_id,
                "input number": i,
                "output": flatten(output)
            })
    return pd.DataFrame(rows)

