def extract_features(task_id):
    x, y = [], [] 
    for obj in task_id['train']:
        x.append(np.array(obj['input']))
        y.append(np.array(obj['output']))
    return x, y

def SameSizeInOut(task_id): 
    return all([np.shape(x)==np.shape(y) for x, y in zip(*extract_features(task_id))])

'''Width In'''
def widthIn(task_id):
    for x, y in zip(*extract_features(task_id)):
       s=  np.shape(x)[1] 
    return s

'''Width Out'''
def widthOut(task_id):
    for x, y in zip(*extract_features(task_id)):
       s=  np.shape(y)[1] 
    return s

'''High In'''
def highIn(task_id):
    for x, y in zip(*extract_features(task_id)):
        s=  np.shape(x)[0] 
    return s

'''High Out'''
def highOut(task_id):
    for x, y in zip(*extract_features(task_id)):
       s=  np.shape(y)[0] 
    return s

def areaIn(task_id):
    for x, y in zip(*extract_features(task_id)): #x - question y - answer
       s=  np.shape(x)[0] * np.shape(x)[1]
    return s

'''Area Out '''
def areaOut(task_id):
    for x, y in zip(*extract_features(task_id)):
       s=  np.shape(y)[0] * np.shape(y)[1]
        
    return s

