import numpy as np

def count_2x2_blocks_of_2s_and_fill(grid):
    grid = np.array(grid)
    rows, cols = grid.shape

    count = 0
    marked = np.zeros_like(grid, dtype=bool)

    for r in range(rows - 1):
        for c in range(cols - 1):
            # Check if it's a 2x2 block of 2s and not already marked
            if (grid[r:r+2, c:c+2] == 2).all() and not marked[r:r+2, c:c+2].any():
                count += 1
                marked[r:r+2, c:c+2] = True  # prevent overlapping detection

    # Create output 3x3 grid
    output = np.zeros((3, 3), dtype=int)
    positions = [
        (0, 0),  
        (0, 2),  
        (1, 1),  
        (2, 0),  
        (2, 2),  
    ]

    for i in range(min(count, 5)):
        r, c = positions[i]
        output[r][c] = 1

    return output
    
import numpy as np

def extract_bl_cks(grid):
    blocks = []
    block = []
    for row in grid:
        if all(val == 5 for val in row):
            if block:
                blocks.append(np.array(block))
                block = []
        else:
            block.append(row)
    if block:
        blocks.append(np.array(block))
    return blocks

def logic_expand_ones(block):
    new_block = block.copy()
    for r in range(block.shape[0]):
        row = block[r]
        first = np.where(row == 1)[0]
        if len(first) > 0:
            start = first[0]
            end = first[-1] + 1
            new_block[r, start:end+2] = 1
    return new_block

def logic_shift_right(block):
    new_block = np.zeros_like(block)
    for r in range(block.shape[0]):
        for c in range(block.shape[1] - 1):
            if block[r, c] != 0:
                new_block[r, c+1] = block[r, c]
    return new_block

def logic_replace_2s_with_3s(block):
    new_block = block.copy()
    for r in range(block.shape[0]):
        twos = np.where(new_block[r] == 2)[0]
        if len(twos) > 0:
            new_block[r, twos[0]] = 3
    return new_block

def logic_replace_2s_with_3s_one_column(block, allowed_cols, already_converted_cols):
    new_block = block.copy()
    next_col = None
    for col in allowed_cols:
        if col not in already_converted_cols:
            next_col = col
            break
    if next_col is None:
        return new_block  # No new column to convert
    for r in range(block.shape[0]):
        if new_block[r, next_col] == 2:
            new_block[r, next_col] = 3
    return new_block

logics = {
    "expand_ones": logic_expand_ones,
    "shift_right": logic_shift_right,
    "replace_2s_with_3s": logic_replace_2s_with_3s
}

def best_fit_logic(block1, block2):
    best_score = -1
    best_logic = None

    for name, func in logics.items():
        try:
            pred = func(block1)
            if pred.shape != block2.shape:
                continue  
            score = np.sum(pred == block2)
            if score > best_score:
                best_score = score
                best_logic = name
        except Exception:
            continue  

    return best_logic

def choose_best_global_logic(blocks):
    logic_counts = {}
    for i in range(len(blocks) - 1):
        name = best_fit_logic(blocks[i], blocks[i+1])
        if name is not None:
            logic_counts[name] = logic_counts.get(name, 0) + 1

    if not logic_counts:
        return None  

    best_logic = max(logic_counts, key=logic_counts.get)
    return best_logic

def get_2_to_3_columns_ordered(blocks):
    ordered_cols = []
    seen = set()
    for i in range(len(blocks) - 1):
        b1, b2 = blocks[i], blocks[i+1]
        for r in range(b1.shape[0]):
            for c in range(b1.shape[1]):
                if b1[r, c] == 2 and b2[r, c] == 3 and c not in seen:
                    ordered_cols.append(c)
                    seen.add(c)
    return sorted(ordered_cols)

def get_already_converted_cols(blocks):
    converted = set()
    for i in range(len(blocks) - 1):
        b1, b2 = blocks[i], blocks[i+1]
        for r in range(b1.shape[0]):
            for c in range(b1.shape[1]):
                if b1[r, c] == 2 and b2[r, c] == 3:
                    converted.add(c)
    return sorted(converted)

def predict_next_block(grid):
    blocks = extract_bl_cks(grid)
    logic_name = choose_best_global_logic(blocks)

    if logic_name is None:
        
        return None 

    last_block = blocks[-1]

    if logic_name == "replace_2s_with_3s":
        allowed_cols = [c for c in range(last_block.shape[1]) if 2 in last_block[:, c]]
        already_converted_cols = get_already_converted_cols(blocks)
        next_block = logic_replace_2s_with_3s_one_column(
            last_block, allowed_cols, already_converted_cols
        )
    else:
        next_block = logics[logic_name](last_block)

    return next_block.tolist()

