import numpy as np
from collections import defaultdict, deque

def fill_rectangles(grid):
    grid = np.array(grid)
    rows, cols = grid.shape
    filled_grid = grid.copy()

    # Step 1: Fill rectangles as per your logic
    for r in range(rows):
        c = 0
        while c < cols:
            if filled_grid[r][c] != 0:
                digit = filled_grid[r][c]
                start_c = c
                # Find the end of this block in this row
                while c < cols and (filled_grid[r][c] == digit or filled_grid[r][c] == 0):
                    c += 1
                end_c = c - 1

                # Find how many rows the block extends downward
                rr = r
                while rr < rows and all(filled_grid[rr][cc] == digit or filled_grid[rr][cc] == 0 for cc in range(start_c, end_c + 1)):
                    rr += 1
                end_r = rr - 1

                # Fill all zeros inside this rectangle
                for row in range(r, end_r + 1):
                    for col in range(start_c, end_c + 1):
                        if filled_grid[row][col] == 0:
                            filled_grid[row][col] = digit
            else:
                c += 1

    # Step 2: Fill starting zeros and any leftover zeros in each row
    for r in range(rows):
        for c in range(cols):
            if filled_grid[r][c] == 0:
                # Look right to find the first non-zero digit
                for right in range(c + 1, cols):
                    if filled_grid[r][right] != 0:
                        filled_grid[r][c] = filled_grid[r][right]
                        break

    return filled_grid.tolist()
    
def identify_noise_digits(grid):
    grid = np.array(grid)
    rows, cols = grid.shape

    all_digits = set()
    repeating_digits = set()

    # Check rows for consecutive repeats
    for r in range(rows):
        c = 0
        while c < cols:
            if grid[r, c] != 0:
                start = c
                while c + 1 < cols and grid[r, c + 1] == grid[r, start]:
                    c += 1
                if c > start:  # Found repetition in row
                    repeating_digits.add(grid[r, start])
            c += 1

    # Check columns for consecutive repeats
    for c in range(cols):
        r = 0
        while r < rows:
            if grid[r, c] != 0:
                start = r
                while r + 1 < rows and grid[r + 1, c] == grid[start, c]:
                    r += 1
                if r > start:  # Found repetition in column
                    repeating_digits.add(grid[start, c])
            r += 1

    # All digits present in the grid (excluding 0)
    for row in grid:
        for val in row:
            if val != 0:
                all_digits.add(val)

    # Noise digits are those that are present but not repeating
    noise_digits = all_digits - repeating_digits

    return list(noise_digits), list(repeating_digits)

def clean_grid_using_noise_and_valid(grid):
    grid = np.array(grid)
    rows, cols = grid.shape
    visited = np.zeros_like(grid, dtype=bool)

    noise_digits, valid_digits = identify_noise_digits(grid)

    def get_neighbors(r, c):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr, nc] != 0 and not visited[nr, nc]:
                yield nr, nc

    def bfs(r, c):
        queue = deque()
        queue.append((r, c))
        block_positions = []
        block_digit = grid[r, c]
        visited[r, c] = True

        while queue:
            cr, cc = queue.popleft()
            block_positions.append((cr, cc))

            for nr, nc in get_neighbors(cr, cc):
                visited[nr, nc] = True
                queue.append((nr, nc))

        return block_positions, block_digit

    for r in range(rows):
        for c in range(cols):
            if grid[r, c] != 0 and not visited[r, c]:
                block_positions, block_digit = bfs(r, c)

                for br, bc in block_positions:
                    if grid[br, bc] in noise_digits:
                        grid[br, bc] = block_digit  # Replace noise inside block with block digit

    # Replace noise digits in background with 0
    for r in range(rows):
        for c in range(cols):
            if grid[r, c] in noise_digits:
                grid[r, c] = 0

    return grid.tolist()

def fill_internal_zeros(grid):
    grid = np.array(grid)
    rows, cols = grid.shape
    visited = np.zeros_like(grid, dtype=bool)

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(start_r, start_c, digit):
        queue = deque()
        queue.append((start_r, start_c))
        visited[start_r, start_c] = True

        block_cells = []
        zero_neighbors = []

        while queue:
            r, c = queue.popleft()
            block_cells.append((r, c))

            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if not visited[nr, nc]:
                        if grid[nr, nc] == digit:
                            visited[nr, nc] = True
                            queue.append((nr, nc))
                        elif grid[nr, nc] == 0:
                            zero_neighbors.append((nr, nc))

        # Fill internal zeros
        for zr, zc in zero_neighbors:
            # Check if this zero is fully surrounded by the block (all non-diagonal neighbors are the block digit or other filled zeros)
            surrounded = True
            for dr, dc in directions:
                nr, nc = zr + dr, zc + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr, nc] != digit:
                        surrounded = False
                        break
            if surrounded:
                grid[zr, zc] = digit

    # Scan the grid to find all blocks
    for r in range(rows):
        for c in range(cols):
            if grid[r, c] != 0 and not visited[r, c]:
                bfs(r, c, grid[r, c])

    return grid.tolist()
    
def remove_zero_lines(grid):
    """Removes all zero rows and zero columns from the grid."""
    cleaned_grid = [row for row in grid if any(val != 0 for val in row)]
    if not cleaned_grid:
        return []

    transposed = list(zip(*cleaned_grid))
    transposed = [col for col in transposed if any(val != 0 for val in col)]
    final_grid = [list(row) for row in zip(*transposed)]

    return final_grid

def fill_border_with_pattern(grid, target_size):
    block = remove_zero_lines(grid)
    pattern = block[0]  # Automatically take the entire first row as the pattern

    filled_grid = [row[:] for row in block]  # Copy the block

    idx = 0
    while len(filled_grid) < target_size or len(filled_grid[0]) < target_size:
        digit = pattern[idx % len(pattern)]

        # Fill the rightmost column
        if len(filled_grid[0]) < target_size:
            for row in filled_grid:
                row.append(digit)

        # Fill the bottom row
        if len(filled_grid) < target_size:
            new_row = [digit] * len(filled_grid[0])
            filled_grid.append(new_row)

        idx += 1

    return filled_grid
def check_grid_size(grid):
    if grid is None or len(grid) == 0 or len(grid[0]) == 0:
        return (0, 0)
    rows = len(grid)
    cols = len(grid[0])
    return (rows, cols)

import numpy as np
from collections import deque

def d_bfs_count(grid, visited, start, target_digit):
    """
    BFS to collect connected cells starting from 'start'.
    Returns the block and the count of target_digit (e.g., '2').
    """
    queue = deque([start])
    block = []
    count_target = 0
    rows, cols = len(grid), len(grid[0])
    visited[start[0]][start[1]] = True

    while queue:
        x, y = queue.popleft()
        block.append((x, y))
        if grid[x][y] == target_digit:
            count_target += 1
        for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and not visited[nx][ny]:
                if grid[nx][ny] != 0:
                    visited[nx][ny] = True
                    queue.append((nx, ny))
    return block, count_target

def extract_block_with_max_digit(grid, target_digit=2):
    """
    Finds and extracts the block that contains the maximum number of the target_digit.
    """
    grid = np.array(grid)
    visited = np.zeros(grid.shape, dtype=bool)

    max_count = -1
    max_block = []

    for i in range(grid.shape[0]):
        for j in range(grid.shape[1]):
            if not visited[i][j] and grid[i][j] != 0:
                block, count_target = d_bfs_count(grid, visited, (i, j), target_digit)
                if count_target > max_count:
                    max_count = count_target
                    max_block = block

    return max_block

def extract_block_to_grid(grid, block):
    """
    Extracts the minimal subgrid containing the block.
    """
    if not block:
        return []

    min_x = min(x for x, y in block)
    max_x = max(x for x, y in block)
    min_y = min(y for x, y in block)
    max_y = max(y for x, y in block)

    extracted = []
    for i in range(min_x, max_x + 1):
        row = []
        for j in range(min_y, max_y + 1):
            row.append(grid[i][j])
        extracted.append(row)

    return extracted
    
from collections import Counter
import numpy as np

def true_dominant_digit(block):
    """Return the most frequent non-zero digit in the block."""
    if isinstance(block, np.ndarray):
        block = block.tolist()

    # Flatten the block safely, ignoring any sublists
    digits = []
    for row in block:
        for d in row:
            if isinstance(d, list):  # Defensive: avoid nested lists
                for x in d:
                    if x != 0:
                        digits.append(x)
            else:
                if d != 0:
                    digits.append(d)

    if not digits:
        return None

    counts = Counter(digits)
    return counts.most_common(1)[0][0]


def vertical_match(grid,color):
    rows, cols = len(grid), len(grid[0])
    vertical_line = find_vertical_line(grid)

    left = [row[:vertical_line] for row in grid]
    right = [row[vertical_line + 1:] for row in grid]

    min_width = min(len(left[0]), len(right[0]))  # Ensure we don't go out of bounds

    result = []
    for i in range(rows):
        row_result = []
        for j in range(min_width):
            if left[i][j] == 0 and right[i][j] == 0:
                row_result.append(0)

            elif left[i][j] != 0 and right[i][j] != 0:
                row_result.append(0)
            else:
                row_result.append(color)
        result.append(row_result)
    return result

def get_other_digits(grid, line_digits):
    """
    Returns the set of unique digits found in the grid excluding line_digits and 0.
    """
    other_digits = set()
    for row in grid:
        for cell in row:
            if cell != 0 and cell not in line_digits:
                other_digits.add(cell)
    return other_digits

def bfs_block(grid, visited, start, excluded_digits):
    """
    BFS to collect all connected cells forming a block, ignoring excluded digits.
    """
    queue = deque([start])
    block = []
    rows, cols = len(grid), len(grid[0])
    visited[start[0]][start[1]] = True

    while queue:
        x, y = queue.popleft()
        block.append((x, y))

        for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:  # 4-connectivity
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and not visited[nx][ny]:
                if grid[nx][ny] not in excluded_digits:
                    visited[nx][ny] = True
                    queue.append((nx, ny))
    return block

def count_blocks_of_other_digits(grid, line_digits):
    """
    Counts the number of separate blocks for each digit (excluding line_digits and 0).
    """
    grid = np.array(grid)
    visited = np.zeros(grid.shape, dtype=bool)
    digit_block_counts = defaultdict(int)

    rows, cols = grid.shape

    for i in range(rows):
        for j in range(cols):
            if not visited[i][j] and grid[i][j] != 0 and grid[i][j] not in line_digits:
                block = bfs_block(grid, visited, (i, j), line_digits)
                digit = grid[i][j]
                digit_block_counts[digit] += 1

    return dict(digit_block_counts)

def arrange_pyramid(digit_block_counts):
    
    if not digit_block_counts:
        return []

    sorted_digits = sorted(digit_block_counts.items(), key=lambda x: x[1])

    rows = []
    for digit, count in sorted_digits:
        row = [digit] * count
        rows.append(row)

    max_width = max(len(row) for row in rows)
    pyramid = []

    for row in rows:
        padding = [0] * (max_width - len(row))
        pyramid.append(row + padding)

    return pyramid

def split_grid_four_parts_cross(grid):
    """
    Splits the grid into four parts by crossing through the center row and center column.
    The center row and center column are excluded.
    """
    rows = len(grid)
    cols = len(grid[0])

    mid_row = rows // 2
    mid_col = cols // 2

    # Top Left: rows before mid_row, columns before mid_col
    top_left = [row[:mid_col] for row in grid[:mid_row]]

    # Top Right: rows before mid_row, columns after mid_col
    top_right = [row[mid_col + 1:] for row in grid[:mid_row]]

    # Bottom Left: rows after mid_row, columns before mid_col
    bottom_left = [row[:mid_col] for row in grid[mid_row + 1:]]

    # Bottom Right: rows after mid_row, columns after mid_col
    bottom_right = [row[mid_col + 1:] for row in grid[mid_row + 1:]]

    return top_left, top_right, bottom_left, bottom_right

def is_single_unique_digit_excluding(grid, exclude_digit):
    """
    Checks if a grid contains only one unique digit excluding the given digit.
    Returns (True, digit) if found, else (False, None).
    """
    digits = set(cell for row in grid for cell in row if cell != exclude_digit)
    if len(digits) == 1:
        return True, digits.pop()
    return False, None

def find_unique_part_excluding_dominant(grid):
    """
    Splits the grid into four parts.
    Returns the part that has a unique digit (excluding the dominant digit).
    """
    dominant = get_dominant_digit(grid)
    tl, tr, bl, br = split_grid_four_parts_cross(grid)
    parts = [tl, tr, bl, br]

    for idx, part in enumerate(parts, 1):
        is_unique, digit = is_single_unique_digit_excluding(part, dominant)
        if is_unique:
            return idx, digit, part  # Return part index, the unique digit, and the part

    return None, None, None  # If no such part found
    
def split_grid_horizontally_from_center(grid):
    
    rows = len(grid)
    mid = rows // 2

    if rows % 2 == 0:
        top = grid[:mid]
        bottom = grid[mid:]
    else:
        top = grid[:mid + 1]  # Include the center row in the top part
        bottom = grid[mid + 1:]

    return top, bottom

def split_and_match_rows(grid, fill_digit):
    
    # Split grid
    top, bottom = split_grid_horizontally_from_center(grid)
    
    # Ensure both parts are same size
    min_rows = min(len(top), len(bottom))
    rows = min_rows
    cols = len(grid[0])

    result = []
    for i in range(rows):
        row = []
        for j in range(cols):
            if top[i][j] == 0 and bottom[i][j] == 0:
                row.append(fill_digit)
            else:
                row.append(0)
        result.append(row)
    
    return result

import numpy as np
def merge_center_lines(grid):
    """
    Merges the two center lines into one by taking the element-wise maximum.
    Useful when a vertically stacked grid has duplicated center rows.
    """
    rows = len(grid)
    cols = len(grid[0])

    if rows % 2 != 0:
        raise ValueError("Grid must have an even number of rows to merge center lines.")

    mid1 = (rows // 2) - 1
    mid2 = rows // 2

    merged_row = [max(grid[mid1][j], grid[mid2][j]) for j in range(cols)]

    # Build new grid by removing mid1 and mid2 and inserting the merged row
    new_grid = grid[:mid1] + [merged_row] + grid[mid2+1:]

    return new_grid

def get_center_digit(grid):
    """
    Returns the digit at the center of the grid.
    For grids with even number of rows or columns, 
    it picks the top-left cell among the four center cells.
    """
    rows = len(grid)
    cols = len(grid[0])

    center_row = rows // 2
    center_col = cols // 2

    # For even-sized grids, choose the top-left center
    if rows % 2 == 0:
        center_row -= 1
    if cols % 2 == 0:
        center_col -= 1

    return grid[center_row][center_col]
    
def stack_grid_vertically(grid):
    """
    Stacks the grid on top of itself vertically (joins a and a).
    """
    return np.vstack([grid, grid])

from collections import Counter

def get_border_digit(grid):
    """
    Returns the most frequent digit found on the border of the grid.
    """
    rows = len(grid)
    cols = len(grid[0])

    border_elements = []

    # Top and bottom rows
    border_elements.extend(grid[0])
    border_elements.extend(grid[-1])

    # Left and right columns (excluding already counted corners)
    for i in range(1, rows - 1):
        border_elements.append(grid[i][0])
        border_elements.append(grid[i][-1])

    # Count frequency of each digit
    digit_counts = Counter(border_elements)

    # Return the most common digit
    border_digit, _ = digit_counts.most_common(1)[0]

    return border_digit

def add_custom_border(grid, border_digit, corner_digit):
    """
    Adds a border around the grid:
    - Corners will have corner_digit
    - Edges will have border_digit
    """
    rows = len(grid)
    cols = len(grid[0])

    new_row = [corner_digit] + [border_digit] * cols + [corner_digit]

    # Start with top border
    result = [new_row[:]]

    # Middle rows with border_digit on sides
    for row in grid:
        result.append([border_digit] + row + [border_digit])

    # Add bottom border
    result.append(new_row[:])

    return result

def fill_non_zero_with_digit(grid, digit):
    
    return [[digit if cell != 0 else 0 for cell in row] for row in grid]

    
def fill_zero_with_digit(grid, fill_digit):
    """
    Fills all non-zero positions in the grid with the specified digit.
    Zeros remain unchanged.
    Returns a new grid as a list of lists.
    """
    filled_grid = []
    for row in grid:
        new_row = [fill_digit if val == 0 else 0 for val in row]
        filled_grid.append(new_row)
    return filled_grid
    
def is_single_digit_grid(grid):
    """Check if a grid contains only one unique non-zero digit."""
    unique_digits = set(cell for row in grid for cell in row if cell != 0)
    return len(unique_digits) == 1

def fill_grid_by_rules_dynamic(grid1, grid2):
    """
    Dynamically assign target and use grids based on content.
    Target grid: the one with a single unique non-zero digit.
    Use grid: the other one.
    Then, fill the target grid according to the specified rules.
    """
    if is_single_digit_grid(grid1):
        target_grid, use_grid = grid1, grid2
    elif is_single_digit_grid(grid2):
        target_grid, use_grid = grid2, grid1
    else:
        # If none are a single-digit grid, return target_grid unchanged
        return grid1

    a = [row[:] for row in target_grid]  # Copy target grid
    rows = len(a)
    cols = len(a[0])

    last_row_b = use_grid[-1]
    first_row_b = use_grid[0]

    min_cols = min(cols, len(last_row_b))  # Safe column range

    for i in range(rows):
        for j in range(min_cols):
            if a[i][j] == 0:
                a[i][j] = last_row_b[j]  # Fill zero cells using last row of b
            else:
                a[i][j] = first_row_b[j]  # Replace non-zero cells with corresponding b column value

    return a
    
def byparts(grid):
    dominant_digit = get_dominant_digit(grid)

    for index, row in enumerate(grid):
        if all(cell == row[0] and cell != 0 and cell != dominant_digit for cell in row):
            upper = grid[:index]
            lower = grid[index+1:]
            return upper, lower

    # Always return two lists
    return grid, []
def de_ruk(a, b):
    # Correct empty check for numpy arrays or lists
    if len(a) == 0 or len(b) == 0:
        return []

    min_rows = min(len(a), len(b))
    min_cols = min(len(a[0]), len(b[0]))

    c = []

    for i in range(min_rows):
        row = []
        for j in range(min_cols):
            if a[i][j] != 0 and b[i][j] != 0:
                row.append(0)
            elif a[i][j] == 0 and b[i][j] == 0:
                row.append(0)
            else:
                row.append(3)
        c.append(row)

    return c  # Already list of lists

from collections import Counter

def get_line_digit_excluding_dominant(grid):
    """Return the most frequent non-zero digit excluding the dominant (most frequent) digit."""
    flat_digits = [cell for row in grid for cell in row if cell != 0]
    counts = Counter(flat_digits)
    
    if not counts:
        return None  # No non-zero digits found

    # Find the dominant (most frequent) digit
    dominant_digit = counts.most_common(1)[0][0]

    # Remove the dominant digit
    counts.pop(dominant_digit)

    if not counts:
        return None  # If no other digits remain

    # Get the next most frequent digit
    line_digit = counts.most_common(1)[0][0]
    return line_digit

def find_row_break_positions(grid, line_digit, dominant_digit):
    """Find break positions where a dominant digit interrupts a full row of line_digit."""
    grid = np.array(grid)
    rows, cols = grid.shape
    break_positions = []

    for r in range(rows):
        # Check if the row is a continuous line of line_digit (or contains dominant digit breaks)
        line_digit_count = np.sum(grid[r] == line_digit)
        if line_digit_count >= (cols * 0.8):  # Optional: If you want to allow minor breaks, else use: if line_digit_count == cols
            for c in range(cols):
                if grid[r][c] == dominant_digit:
                    break_positions.append((r, c))

    return break_positions

def takeout_block(grid, positions):
    """Extract the minimal bounding block that contains all the given positions. Return None if no positions."""
    if not positions:
        return None

    rows = [r for r, c in positions]
    cols = [c for r, c in positions]

    min_row, max_row = min(rows), max(rows)
    min_col, max_col = min(cols), max(cols)

    block = grid[min_row:max_row+1, min_col:max_col+1]
    return block

    
