import numpy as np
from collections import deque

# --------------------- Method 1: BFS Largest Connected Block ---------------------

def bfs_largest_block(grid, visited, start):
    """Perform BFS to get all connected non-zero cells."""
    queue = deque([start])
    connected = []
    visited[start[0], start[1]] = True
    color = grid[start[0], start[1]]

    while queue:
        x, y = queue.popleft()
        connected.append((x, y))

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < grid.shape[0] and 0 <= ny < grid.shape[1]:
                if not visited[nx, ny] and grid[nx, ny] == color:
                    visited[nx, ny] = True
                    queue.append((nx, ny))

    return connected

def extract_largest_block(grid):
    """Extract the largest connected non-zero block from the grid."""
    grid = np.array(grid)
    visited = np.zeros_like(grid, dtype=bool)
    max_block = []
    max_size = 0

    for i in range(grid.shape[0]):
        for j in range(grid.shape[1]):
            if not visited[i, j] and grid[i, j] != 0:
                block = bfs_largest_block(grid, visited, (i, j))
                if len(block) > max_size:
                    max_size = len(block)
                    max_block = block

    if not max_block:
        return []

    # Extract the rectangular slice
    xs, ys = zip(*max_block)
    min_x, max_x = min(xs), max(xs)
    min_y, max_y = min(ys), max(ys)
    largest_rect_block = grid[min_x:max_x+1, min_y:max_y+1]

    return largest_rect_block.tolist()

# --------------------- Method 2: Largest Bordered Rectangle ---------------------

def find_largest_bordered_rectangle(grid):
    """Find the largest bordered rectangle where all four borders are non-zero."""
    grid = np.array(grid)
    max_area = 0
    best_block = None
    rows, cols = grid.shape

    for top in range(rows):
        for left in range(cols):
            if grid[top, left] == 0:
                continue
            for bottom in range(top + 2, rows):
                for right in range(left + 2, cols):
                    if grid[top, right] == 0 or grid[bottom, left] == 0 or grid[bottom, right] == 0:
                        continue
                    if (np.all(grid[top, left:right+1] != 0) and
                        np.all(grid[bottom, left:right+1] != 0) and
                        np.all(grid[top:bottom+1, left] != 0) and
                        np.all(grid[top:bottom+1, right] != 0)):
                        area = (bottom - top + 1) * (right - left + 1)
                        if area > max_area:
                            max_area = area
                            best_block = grid[top:bottom+1, left:right+1]

    if best_block is None:
        return []

    return best_block.tolist()

# --------------------- Common Border Removal Function ---------------------

def remove_border_from_block(block):
    """Remove the border from a block."""
    block = np.array(block)
    if block.shape[0] <= 2 or block.shape[1] <= 2:
        return []
    inner_block = block[1:-1, 1:-1]
    return inner_block.tolist()
    
import numpy as np
from collections import deque, Counter

def d_bfs(grid, visited, start):
    """Find all connected non-zero cells using four-connectivity."""
    queue = deque([start])
    connected = []
    visited[start[0], start[1]] = True

    while queue:
        x, y = queue.popleft()
        connected.append((x, y))

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < grid.shape[0] and 0 <= ny < grid.shape[1]:
                if not visited[nx, ny] and grid[nx, ny] != 0:
                    visited[nx, ny] = True
                    queue.append((nx, ny))
    return connected

def block_extraction(grid, connected_cells):
    """Extract the smallest rectangle containing all connected cells."""
    xs, ys = zip(*connected_cells)
    min_x, max_x = min(xs), max(xs)
    min_y, max_y = min(ys), max(ys)
    return grid[min_x:max_x+1, min_y:max_y+1].tolist()

def extract_all_blocks(grid):
    """Extract all unique rectangular blocks from the grid."""
    grid = np.array(grid)
    visited = np.zeros(grid.shape, dtype=bool)
    blocks = []

    for i in range(grid.shape[0]):
        for j in range(grid.shape[1]):
            if not visited[i, j] and grid[i, j] != 0:
                connected = d_bfs(grid, visited, (i, j))
                block = block_extraction(grid, connected)
                blocks.append(block)

    return blocks

def get_dominant_digit(block):
    """Return the most frequent non-zero digit in the block."""
    digits = [d for row in block for d in row if d != 0]
    if not digits:
        return None
    return Counter(digits).most_common(1)[0][0]

def count_pluses(block, dominant_digit):
    """Count the number of plus signs in the block, excluding zeros and the dominant digit."""
    block = np.array(block)
    count = 0

    for i in range(1, block.shape[0] - 1):
        for j in range(1, block.shape[1] - 1):
            digit = block[i, j]
            if digit != 0 and digit != dominant_digit:
                if (block[i - 1, j] == digit and
                    block[i + 1, j] == digit and
                    block[i, j - 1] == digit and
                    block[i, j + 1] == digit):
                    count += 1
    return count

def find_max_plus_block(grid):
    """Find the block with the maximum number of plus signs."""
    blocks = extract_all_blocks(grid)
    max_count = -1
    max_block = None
    max_index = -1

    for idx, block in enumerate(blocks):
        dominant_digit = get_dominant_digit(block)
        plus_count = count_pluses(block, dominant_digit)
        # print(f"Block {idx + 1}: Plus count = {plus_count}")

        if plus_count > max_count:
            max_count = plus_count
            max_block = block
            max_index = idx + 1

    return max_block, max_index, max_count
    
import numpy as np
from collections import deque, Counter

def remove_duplicate_rows_and_columns(grid):
    grid = np.array(grid)

    # Step 1: Remove duplicate rows
    unique_rows = []
    for row in grid:
        if len(unique_rows) == 0 or not np.array_equal(row, unique_rows[-1]):
            unique_rows.append(row)
    unique_rows = np.array(unique_rows)

    # Step 2: Remove duplicate columns
    transposed = unique_rows.T
    unique_cols = []
    for col in transposed:
        if len(unique_cols) == 0 or not np.array_equal(col, unique_cols[-1]):
            unique_cols.append(col)
    compressed_grid = np.array(unique_cols).T

    return compressed_grid.tolist()
    
def bfs_four_connected(grid, visited, start):
    """Four-connectivity BFS that returns all connected cells of the same digit."""
    queue = deque()
    queue.append(start)
    connected = []
    color = grid[start[0], start[1]]
    visited[start[0], start[1]] = True

    while queue:
        x, y = queue.popleft()
        connected.append((x, y))

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < grid.shape[0] and 0 <= ny < grid.shape[1]:
                if not visited[nx, ny] and grid[nx, ny] == color:
                    visited[nx, ny] = True
                    queue.append((nx, ny))

    return connected

def find_greatest_four_connected(grid):
    """Find the largest four-connected block excluding zeros."""
    nrows, ncols = grid.shape
    visited = np.zeros((nrows, ncols), dtype=bool)
    max_connected = []

    for i in range(nrows):
        for j in range(ncols):
            if not visited[i, j] and grid[i, j] != 0:
                connected = bfs_four_connected(grid, visited, (i, j))
                if len(connected) > len(max_connected):
                    max_connected = connected

    return max_connected

def get_block(grid, connected_cells):
    """Extract the minimal bounding rectangle and remove extra empty rows/columns."""
    if not connected_cells:
        return []
    xs, ys = zip(*connected_cells)
    min_x, max_x = min(xs), max(xs)
    min_y, max_y = min(ys), max(ys)
    block = grid[min_x:max_x+1, min_y:max_y+1]

    # Trim extra empty rows and columns if present
    mask = (block != 0)
    row_mask = mask.any(axis=1)
    col_mask = mask.any(axis=0)
    trimmed_block = block[row_mask][:, col_mask]

    return trimmed_block

def inner_number(block):
    """Find the most frequent digit inside the block, excluding zeros (but allowing border digits)."""
    if block.shape[0] <= 2 or block.shape[1] <= 2:
        return None  # No inner region

    inner_block = block[1:-1, 1:-1].flatten()
    inner_block = [v for v in inner_block if v != 0]

    if len(inner_block) == 0:
        return None

    most_common = Counter(inner_block).most_common(1)[0][0]
    return most_common

def fill_border_block(block, digit):
    """Fill the border of a block with the given digit."""
    block_copy = block.copy()
    rows, cols = block_copy.shape

    for j in range(cols):
        block_copy[0, j] = digit
        block_copy[rows - 1, j] = digit

    for i in range(1, rows - 1):
        block_copy[i, 0] = digit
        block_copy[i, cols - 1] = digit

    return block_copy.tolist()

import numpy as np

def extract_pattern_from_block(grid, background=0):
    """
    Extract the minimal rectangular block that contains all non-background digits.
    """
    grid = np.array(grid)
    positions = np.argwhere(grid != background)

    if positions.size == 0:
        return []  # No pattern found

    min_row, min_col = positions.min(axis=0)
    max_row, max_col = positions.max(axis=0)

    # Extract the minimal rectangle
    block = grid[min_row:max_row+1, min_col:max_col+1]

    return block.tolist(), min_row, min_col, max_row, max_col


def scale_block_2x2(block):
    """
    Scale the block by 2x: make each cell a 2x2 block.
    """
    block = np.array(block)
    nrows, ncols = block.shape

    # Create a new grid of double size
    expanded = np.zeros((nrows * 2, ncols * 2), dtype=int)

    for i in range(nrows):
        for j in range(ncols):
            value = block[i, j]
            expanded[2*i:2*i+2, 2*j:2*j+2] = value

    return expanded.tolist()


def extract_and_scale(grid, background=0):
    result = extract_pattern_from_block(grid, background)

    if not result or len(result) != 5:
        return None  # Safe fallback if result is invalid

    block, _, _, _, _ = result

    if not block:
        return None  # No usable pattern found

    expanded_block = scale_block_2x2(block)
    return expanded_block

    
