import numpy as np
from scipy.ndimage import label

def ensure_2d(grid):
    """Ensure the grid is strictly 2D by squeezing extra dimensions."""
    grid = np.array(grid)
    grid = np.squeeze(grid)  # Removes singleton dimensions like (1, N, N)

    if grid.ndim != 2:
        return None  # Return None for invalid grids
    return grid

def find_most_frequent_digit(grid):
    grid = ensure_2d(grid)
    if grid is None:
        return None

    unique, counts = np.unique(grid, return_counts=True)
    most_frequent_digit = unique[np.argmax(counts)]
    return most_frequent_digit

def find_most_frequent_digit_excluding_background(grid, background):
    grid = ensure_2d(grid)
    if grid is None:
        return None

    foreground_values = grid[grid != background]
    if foreground_values.size == 0:
        return None  # No foreground present

    unique, counts = np.unique(foreground_values, return_counts=True)
    most_frequent_digit = unique[np.argmax(counts)]
    return most_frequent_digit

def extract_blocks_after_removing_background(grid, background):
    grid = ensure_2d(grid)
    if grid is None:
        return []

    structure = np.ones((3, 3), dtype=int)  # 8-connectivity
    labeled_grid, num_features = label(grid != background, structure=structure)

    blocks = []
    for block_num in range(1, num_features + 1):
        positions = np.argwhere(labeled_grid == block_num)
        if positions.size == 0:
            continue  # Skip empty blocks

        min_row, min_col = positions.min(axis=0)
        max_row, max_col = positions.max(axis=0)

        block = grid[min_row:max_row + 1, min_col:max_col + 1]
        mask = labeled_grid[min_row:max_row + 1, min_col:max_col + 1] == block_num

        cleaned_block = np.full(block.shape, background)
        cleaned_block[mask] = block[mask]

        blocks.append(cleaned_block)

    return blocks

def smart_merge_blocks_multiple(blocks, background):
    """Merge multiple blocks sequentially, skipping invalid ones."""
    valid_blocks = [ensure_2d(block) for block in blocks if ensure_2d(block) is not None]

    if not valid_blocks:
        return []  # Return empty list if no valid blocks

    merged = np.full(valid_blocks[0].shape, background)

    for block in valid_blocks:
        if block.shape != merged.shape:
            # If sizes mismatch, skip the block
            continue

        rows, cols = block.shape
        for r in range(rows):
            for c in range(cols):
                val = block[r, c]
                if val != background:
                    merged[r, c] = val  # Always place foreground digit

    return merged.tolist()
from collections import deque
from typing import List, Optional, Any
import numpy as np

def smallest_filled_rectangle(grid: List[List[int]],
                              ignore_background: Optional[int] = 0,
                              require_fully_filled: bool = True,
                              return_all: bool = False) -> Optional[Any]:
    
    arr = np.array(grid)
    if arr.ndim != 2:
        raise ValueError("grid must be 2D")

    n, m = arr.shape
    visited = np.zeros((n, m), dtype=bool)
    candidates = []

    def neighbors(r, c):
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            rr, cc = r+dr, c+dc
            if 0 <= rr < n and 0 <= cc < m:
                yield rr, cc

    for i in range(n):
        for j in range(m):
            if visited[i, j]:
                continue
            val = arr[i, j]
            if ignore_background is not None and val == ignore_background:
                visited[i, j] = True
                continue

            # BFS to collect component of same digit
            q = deque()
            q.append((i, j))
            visited[i, j] = True
            comp = [(i, j)]
            while q:
                r, c = q.popleft()
                for rr, cc in neighbors(r, c):
                    if not visited[rr, cc] and arr[rr, cc] == val:
                        visited[rr, cc] = True
                        q.append((rr, cc))
                        comp.append((rr, cc))

            # compute bbox
            rows = [p[0] for p in comp]
            cols = [p[1] for p in comp]
            r0, r1 = min(rows), max(rows)
            c0, c1 = min(cols), max(cols)
            area = (r1 - r0 + 1) * (c1 - c0 + 1)

            # check fully filled if requested
            bbox_slice = arr[r0:r1+1, c0:c1+1]
            is_fully_filled = bool(np.all(bbox_slice == val))

            if require_fully_filled and not is_fully_filled:
                # skip incomplete bboxes when fully-filled required
                continue

            # store subgrid and area
            candidates.append({
                "area": int(area),
                "subgrid": bbox_slice.tolist()
            })

    if not candidates:
        return [] if return_all else None

    # sort by area (ascending)
    candidates.sort(key=lambda x: x['area'])

    if return_all:
        # return only the list of subgrids
        return [c['subgrid'] for c in candidates]
    else:
        # return only the smallest subgrid (2D list)
        return candidates[0]['subgrid']

