import numpy as np

from collections import defaultdict

def count_digits(grid):
    digit_counts = defaultdict(int)
    for row in grid:
        for value in row:
            if value != 0:
                digit_counts[value] += 1
    return digit_counts
    
def build_full_concentric_square(digit_counts,max_count):
    # Sort digits by count descending, then by digit descending
    sorted_digits = sorted(digit_counts.items(), key=lambda x: (-x[1], -x[0]))
    digits = [digit for digit, _ in sorted_digits]
    
    # âœ… Correct grid size
    num_layers = len(digits)
    size = max_count  

    block = [[0 for _ in range(size)] for _ in range(size)]

    for layer in range(num_layers):
        digit = digits[layer]
        for i in range(layer, size - layer):
            for j in range(layer, size - layer):
                block[i][j] = digit

    return np.array(block).tolist()
from collections import deque

def find_largest_component_grid(grid):
    grid = np.array(grid)
    rows, cols = grid.shape
    visited = np.zeros((rows, cols), dtype=bool)

    def bfs(r, c, value):
        queue = deque()
        queue.append((r, c))
        visited[r][c] = True
        count = 1

        while queue:
            cr, cc = queue.popleft()

            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = cr + dr, cc + dc

                if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc] == value:
                    visited[nr][nc] = True
                    queue.append((nr, nc))
                    count += 1

        return count

    max_count = 0
    max_value = None

    for r in range(rows):
        for c in range(cols):
            if not visited[r][c] and grid[r][c] != 0:
                component_size = bfs(r, c, grid[r][c])
                if component_size > max_count:
                    max_count = component_size
                    max_value = grid[r][c]

    if max_value is not None:
        return [[int(max_value), int(max_value)], [int(max_value), int(max_value)]]
        
import numpy as np
from collections import deque, Counter

def expand_with_border(grid):
    grid = np.array(grid)

    # Proper empty check
    if grid.size == 0:
        raise ValueError("Input grid cannot be empty.")

    rows, cols = grid.shape

    # Create a new grid with an extra border
    new_grid = np.zeros((rows + 2, cols + 2), dtype=int)

    # Place the original grid in the center
    new_grid[1:rows + 1, 1:cols + 1] = grid

    # Fill top and bottom borders
    new_grid[0, 1:cols + 1] = grid[0]
    new_grid[-1, 1:cols + 1] = grid[-1]

    # Fill left and right borders
    new_grid[1:rows + 1, 0] = grid[:, 0]
    new_grid[1:rows + 1, -1] = grid[:, -1]

    return new_grid.tolist()

import numpy as np
from collections import Counter

def find_partition_rectangles_with_positions(grid, line_digit):
    """Extract rectangles separated by the given line digit, including their positions."""
    grid = np.array(grid)
    rows, cols = grid.shape

    # Find the horizontal lines
    horizontal_lines = []
    for r in range(rows):
        if all(cell == line_digit for cell in grid[r]):
            horizontal_lines.append(r)
    if 0 not in horizontal_lines:
        horizontal_lines = [-1] + horizontal_lines
    if rows - 1 not in horizontal_lines:
        horizontal_lines = horizontal_lines + [rows]

    # Find the vertical lines
    vertical_lines = []
    for c in range(cols):
        if all(grid[r][c] == line_digit for r in range(rows)):
            vertical_lines.append(c)
    if 0 not in vertical_lines:
        vertical_lines = [-1] + vertical_lines
    if cols - 1 not in vertical_lines:
        vertical_lines = vertical_lines + [cols]

    rectangles = []

    # Extract rectangles with positions
    for i in range(len(horizontal_lines) - 1):
        row_start = horizontal_lines[i] + 1
        row_end = horizontal_lines[i + 1]
        if row_start >= row_end:
            continue

        row_rectangles = []
        for j in range(len(vertical_lines) - 1):
            col_start = vertical_lines[j] + 1
            col_end = vertical_lines[j + 1]
            if col_start >= col_end:
                continue

            rectangle = grid[row_start:row_end, col_start:col_end]
            row_rectangles.append({
                'row': i,
                'col': j,
                'rect': rectangle
            })

        if row_rectangles:
            rectangles.append(row_rectangles)

    return rectangles

def extract_digit_layout(rectangles):
    """Return the digit layout from the cropped rectangles maintaining grid positions."""
    if not rectangles:  # If rectangles is empty, return a fallback
        return [[0]]  # Fallback: 1x1 grid with zero

    digit_layout = []
    max_cols = max(len(row) for row in rectangles)

    for row_rectangles in rectangles:
        row_digits = []
        for rect_info in row_rectangles:
            rect = rect_info['rect']
            non_zero_digits = set(rect.flatten())
            if 0 in non_zero_digits:
                non_zero_digits.remove(0)

            if len(non_zero_digits) == 1:
                digit = list(non_zero_digits)[0]
                row_digits.append(digit)
            else:
                row_digits.append(0)  # If not a clean block, fill with 0

        while len(row_digits) < max_cols:
            row_digits.append(0)  # Pad row to max columns

        digit_layout.append(row_digits)

    while len(digit_layout) < max_cols:
        digit_layout.append([0] * max_cols)  # Pad to square grid

    return digit_layout

def center_in_square_grid(digit_layout, final_size=None):
    """Center the digit layout in a larger square grid padded with 0s."""
    digit_layout = np.array(digit_layout)
    size = max(digit_layout.shape)

    if final_size is not None:
        size = max(size, final_size)

    if size % 2 == 0:
        size += 1  # Ensure the final grid is odd-sized for centering

    centered_grid = np.zeros((size, size), dtype=int)

    start_row = (size - digit_layout.shape[0]) // 2
    start_col = (size - digit_layout.shape[1]) // 2

    centered_grid[start_row:start_row + digit_layout.shape[0],
                  start_col:start_col + digit_layout.shape[1]] = digit_layout

    return centered_grid.tolist()

def crop_to_content(grid):
    """Crop the grid to the minimal rectangle that contains all non-zero digits."""
    grid = np.array(grid)
    non_zero_indices = np.argwhere(grid != 0)

    if non_zero_indices.size == 0:
        return [[]]  # Return empty if no content

    min_row, min_col = non_zero_indices.min(axis=0)
    max_row, max_col = non_zero_indices.max(axis=0)

    cropped_grid = grid[min_row:max_row + 1, min_col:max_col + 1]
    return cropped_grid.tolist()
    
def get_line_digits(grid):
    """Return the most frequent non-zero digit(s) which are the line digits."""
    flat_digits = [cell for row in grid for cell in row if cell != 0]
    counts = Counter(flat_digits)
    max_freq = max(counts.values())
    line_digits = [digit for digit, freq in counts.items() if freq == max_freq]
    return line_digits

def find_partition_rectangles(grid, line_digit):
    grid = np.array(grid)
    rows, cols = grid.shape

    # Find the horizontal lines (row indices where the entire row is filled with line_digit)
    horizontal_lines = []
    for r in range(rows):
        if all(cell == line_digit for cell in grid[r]):
            horizontal_lines.append(r)
    # Add edges if not fully bordered
    if 0 not in horizontal_lines:
        horizontal_lines = [-1] + horizontal_lines
    if rows - 1 not in horizontal_lines:
        horizontal_lines = horizontal_lines + [rows]

    # Find the vertical lines (column indices where the entire column is filled with line_digit)
    vertical_lines = []
    for c in range(cols):
        if all(grid[r][c] == line_digit for r in range(rows)):
            vertical_lines.append(c)
    if 0 not in vertical_lines:
        vertical_lines = [-1] + vertical_lines
    if cols - 1 not in vertical_lines:
        vertical_lines = vertical_lines + [cols]

    rectangles = []

    # Now extract the rectangles between the lines
    for i in range(len(horizontal_lines) - 1):
        row_start = horizontal_lines[i] + 1
        row_end = horizontal_lines[i + 1]
        if row_start >= row_end:
            continue

        for j in range(len(vertical_lines) - 1):
            col_start = vertical_lines[j] + 1
            col_end = vertical_lines[j + 1]
            if col_start >= col_end:
                continue

            rectangle = grid[row_start:row_end, col_start:col_end]
            rectangles.append(rectangle)

    return rectangles

def find_single_digit_rectangles(rectangles):
    selected_rectangles = []

    for idx, rect in enumerate(rectangles):
        non_zero_digits = set(rect.flatten())
        if 0 in non_zero_digits:
            non_zero_digits.remove(0)

        if len(non_zero_digits) == 1:
            digit = list(non_zero_digits)[0]
            selected_rectangles.append(rect)

    return selected_rectangles
    
