from collections import deque

def find_vertical_line(grid):
    return len(grid[0]) // 2  # Middle index

def compare_tiles_exact(grid):
    rows, cols = len(grid), len(grid[0])
    vertical_line = find_vertical_line(grid)

    left = [row[:vertical_line] for row in grid]
    right = [row[vertical_line + 1:] for row in grid]

    min_width = min(len(left[0]), len(right[0]))  # Ensure we don't go out of bounds

    result = []
    for i in range(rows):
        row_result = []
        for j in range(min_width):
            if left[i][j] == 0 and right[i][j] == 0:
                row_result.append(0)
            else:
                row_result.append(1)
        result.append(row_result)
    return result

def print_grid(grid):
    for row in grid:
        print(row)

def apply_alternating_tile_flip_rule(grid: np.ndarray, rule):
    reps = rule.get("reps", 3)
    return generate_alternating_tile_flip(np.asarray(grid), reps=reps)
    
def extract_alternating_tile_flip_rule(input_grid: np.ndarray, output_grid: np.ndarray):
    input_grid = np.asarray(input_grid)
    output_grid = np.asarray(output_grid)

    reps_h = output_grid.shape[0] // input_grid.shape[0]
    reps_w = output_grid.shape[1] // input_grid.shape[1]

    if reps_h <= 0 or reps_w <= 0:
        return None

    gen = generate_alternating_tile_flip(input_grid, reps=reps_h)
    if np.array_equal(gen, output_grid):
        return {"type": "horizontal_flip_on_odd_rows", "reps": reps_h}
    return None

def find_common_digit_in_components(grid, components):
    component_digit_sets = []

    for comp in components:
        digits = set()
        for r, c in comp:
            digits.add(grid[r][c])
        component_digit_sets.append(digits)

    common_digits = set.intersection(*component_digit_sets)

    if common_digits:
        return common_digits.pop()
    else:
        return None

def build_3x3_pattern(grid, components, common_digit):
    pattern_grid = [[0 for _ in range(3)] for _ in range(3)]
    center_r, center_c = 1, 1
    pattern_grid[center_r][center_c] = common_digit

    for comp in components:
        digit_positions = [(r, c) for r, c in comp if grid[r][c] == common_digit]

        if not digit_positions:
            continue  # Skip components without the common digit

        base_r, base_c = digit_positions[0]  # Use the first occurrence of the common digit in the component

        for r, c in comp:
            if grid[r][c] != 0 and grid[r][c] != common_digit:
                dr = r - base_r  # Row offset relative to the common digit
                dc = c - base_c  # Column offset relative to the common digit

                # Place in the 3x3 grid if within bounds
                new_r = center_r + dr
                new_c = center_c + dc

                if 0 <= new_r < 3 and 0 <= new_c < 3:
                    pattern_grid[new_r][new_c] = grid[r][c]

    return pattern_grid
    
def print_grid(grid):
    for row in grid:
        print(row)

