from collections import Counter

def largest_rectangular_block(grid):
    rows, cols = len(grid), len(grid[0])
    max_area = 0
    max_rect = {'top_left': (0, 0), 'bottom_right': (0, 0), 'area': 0}

    unique_values = set(val for row in grid for val in row)

    for value in unique_values:
        heights = [0] * cols

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == value:
                    heights[c] += 1
                else:
                    heights[c] = 0

            stack = []
            c = 0
            while c <= cols:
                h = heights[c] if c < cols else 0
                if not stack or h >= heights[stack[-1]]:
                    stack.append(c)
                    c += 1
                else:
                    top = stack.pop()
                    width = c if not stack else c - stack[-1] - 1
                    area = heights[top] * width

                    if area > max_area:
                        max_area = area
                        height = heights[top]
                        end_col = c - 1
                        start_col = end_col - width + 1
                        end_row = r
                        start_row = end_row - height + 1

                        max_rect = {
                            'top_left': (start_row, start_col),
                            'bottom_right': (end_row, end_col),
                            'area': area,
                            'width': width,
                            'height': height,
                            'value': value
                        }

    return max_rect

def extract_background_to_left(grid, block_info, offset=4):
    top_left = block_info['top_left']
    bottom_right = block_info['bottom_right']

    block_start_row = top_left[0]
    block_end_row = bottom_right[0]
    block_start_col = top_left[1]
    block_end_col = bottom_right[1]

    block_height = block_info['height']
    block_width = block_info['width']

    # Calculate the starting column to the left of the block
    background_start_col = max(0, block_start_col - offset)

    replacement_block = []
    for row_idx in range(block_start_row, block_end_row + 1):
        # Repeat the pattern to fill the block width
        pattern = grid[row_idx][background_start_col:block_start_col]
        if len(pattern) == 0:
             # fallback in case offset is too big
            pattern = grid[row_idx][:block_start_col]

        pattern_length = len(pattern)
        if pattern_length == 0:  # nothing to use
            replacement_block.append([0] * block_width)
            continue

        # Extend the pattern to fill the block width
        full_row = []
        while len(full_row) < block_width:
            full_row.extend(pattern)
        full_row = full_row[:block_width]  # Trim if overfilled

        replacement_block.append(full_row)

    return replacement_block

def is_rectangular_block_to_left_of_largest_block(grid, block_info):
    from collections import deque

    rows, cols = len(grid), len(grid[0])
    top_row = block_info['top_left'][0]
    bottom_row = block_info['bottom_right'][0]
    left_col = block_info['top_left'][1]

    largest_value = block_info['value']

    visited = [[False for _ in range(cols)] for _ in range(rows)]

    def bfs(start_r, start_c, value):
        queue = deque()
        queue.append((start_r, start_c))
        visited[start_r][start_c] = True

        min_row, max_row = start_r, start_r
        min_col, max_col = start_c, start_c

        cells = [(start_r, start_c)]

        while queue:
            r, c = queue.popleft()

            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc

                if (top_row <= nr <= bottom_row and 0 <= nc < left_col and
                        not visited[nr][nc] and grid[nr][nc] == value):
                    visited[nr][nc] = True
                    queue.append((nr, nc))
                    cells.append((nr, nc))

                    min_row = min(min_row, nr)
                    max_row = max(max_row, nr)
                    min_col = min(min_col, nc)
                    max_col = max(max_col, nc)

        width = max_col - min_col + 1
        height = max_row - min_row + 1

        # A valid rectangular block must have at least width 2 and height 2
        if width < 2 or height < 2:
            return False

        # Check if the entire rectangle is filled with the same value
        for r in range(min_row, max_row + 1):
            for c in range(min_col, max_col + 1):
                if grid[r][c] != value:
                    return False  # Not fully filled

        return True  # Valid rectangular block found

    for r in range(top_row, bottom_row + 1):
        for c in range(left_col):
            if not visited[r][c]:
                current_value = grid[r][c]
                
                # Skip the largest blockâ€™s value
                if current_value == largest_value:
                    visited[r][c] = True
                    continue

                if bfs(r, c, current_value):
                    return True  # Found another rectangular block to the left

    return False  # No other rectangular block found to the left

def decide_offset_based_on_nearby_blocks(grid, block_info):
    if is_rectangular_block_to_left_of_largest_block(grid, block_info):
        return 3
    else:
        return 4

