import numpy as np


from collections import deque

def deg(grid):
    if isinstance(grid, np.ndarray):
        grid = grid.tolist()

    doubled_rows = [row + row for row in grid]
    doubled_grid = doubled_rows + doubled_rows
    return doubled_grid

def moc(grid):
    """
    For each non-zero digit in the grid, mark its four diagonal neighbors with 8
    if and only if the neighbor is currently 0.
    """
    rows = len(grid)
    cols = len(grid[0])

    # Deep copy to avoid overwriting original
    result = [row[:] for row in grid]

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] != 0:
                # 4 diagonal positions (corners)
                for dx, dy in [(-1, -1), (-1, 1), (1, -1), (1, 1)]:
                    ni, nj = i + dx, j + dy
                    if 0 <= ni < rows and 0 <= nj < cols:
                        if grid[ni][nj] == 0:  # Only fill if the current position is zero
                            result[ni][nj] = 8

    return result

def split_grid_on_horizontal_lines(grid):
    """
    Splits the grid into two parts at the first full horizontal line (row with all non-zero elements).
    Returns the two parts as (a, b), both as tuples of tuples.
    """
    for index, row in enumerate(grid):
        if all(cell != 0 for cell in row):  # detect a horizontal line (no zeros in the row)
            a = tuple(tuple(r) for r in grid[:index])  # upper part
            b = tuple(tuple(r) for r in grid[index+1:])  # lower part
            return (a, b)

    # If no horizontal line is found
    a = tuple(tuple(r) for r in grid)
    b = ()
    return (a, b)

def create_c(a, b):
    """
    Creates a new grid 'c' where each position is checked:
    If both a[i][j] == 0 and b[i][j] == 0, then c[i][j] = 8
    Else, c[i][j] = 0

    Compares only the overlapping area.
    """
    # If either a or b is empty, return an empty grid
    if not a or not b:
        return ()

    min_rows = min(len(a), len(b))
    min_cols = min(len(a[0]), len(b[0]))

    c = []

    for i in range(min_rows):
        row = []
        for j in range(min_cols):
            if a[i][j] == 0 and b[i][j] == 0:
                row.append(8)
            else:
                row.append(0)
        c.append(tuple(row))

    return tuple(c)

def bfs(grid, visited, start):
    queue = deque([start])
    component = []
    rows, cols = len(grid), len(grid[0])
    visited[start[0]][start[1]] = True

    while queue:
        x, y = queue.popleft()
        component.append((x, y))

        for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and not visited[nx][ny] and grid[nx][ny] != 0:
                visited[nx][ny] = True
                queue.append((nx, ny))
    return component

def find_components(grid):
    rows, cols = len(grid), len(grid[0])
    visited = [[False for _ in range(cols)] for _ in range(rows)]
    components = []

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] != 0 and not visited[i][j]:
                component = bfs(grid, visited, (i, j))
                components.append(component)

    return components

def extract_window(grid, component, window_size=3):
    rows, cols = len(grid), len(grid[0])
    xs = [x for x, y in component]
    ys = [y for x, y in component]
    min_x, min_y = min(xs), min(ys)

    window = []
    for i in range(min_x, min_x + window_size):
        row = []
        for j in range(min_y, min_y + window_size):
            if 0 <= i < rows and 0 <= j < cols:
                row.append(grid[i][j])
            else:
                row.append(0)
        window.append(row)
    return window

def crystal(grid):
    grid = np.array(grid)
    components = find_components(grid)

    if not components:
        return [[0]*3 for _ in range(3)]

    # Pick the component with the smallest (min_x, min_y)
    components.sort(key=lambda comp: (min(x for x, y in comp), min(y for x, y in comp)))
    selected_component = components[0]

    return extract_window(grid, selected_component)


def extracting_patterns(grid):
    rows, cols = len(grid), len(grid[0])
    visited = [[False for _ in range(cols)] for _ in range(rows)]
    patterns = []

    def bfs(r, c):
        queue = deque()
        queue.append((r, c))
        pattern = []
        visited[r][c] = True

        while queue:
            x, y = queue.popleft()
            pattern.append((x, y))

            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < rows and 0 <= ny < cols and not visited[nx][ny] and grid[nx][ny] != 0:
                    visited[nx][ny] = True
                    queue.append((nx, ny))
        return pattern

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] != 0 and not visited[i][j]:
                pattern = bfs(i, j)
                if len(pattern) > 1:  # Exclude single-cell patterns
                    patterns.append(pattern)

    # Prepare all digit positions
    digit_positions = {(x, y): grid[x][y] for x in range(rows) for y in range(cols) if grid[x][y] != 0}

    # Mark all cells that are part of patterns
    pattern_cells = set()
    for pattern in patterns:
        pattern_cells.update(pattern)

    used_digits = set()

    cropped_patterns = []
    pattern_positions = []

    for pattern in patterns:
        pattern_set = set(pattern)

        # Candidate digits: digits not part of any pattern or not yet used
        candidate_digits = [(pos, digit_positions[pos]) for pos in digit_positions
                            if pos not in pattern_set and pos not in pattern_cells and pos not in used_digits]

        # If no external digits are available, include single-cell digits not in other patterns
        if not candidate_digits:
            candidate_digits = [(pos, digit_positions[pos]) for pos in digit_positions
                                if pos not in pattern_set and pos not in used_digits]

        min_dist = float('inf')
        nearest_digit = None
        nearest_digit_pos = None
        
        for (x, y), digit in candidate_digits:
            for px, py in pattern:
                dist = abs(px - x) + abs(py - y)
                if dist < min_dist:
                    min_dist = dist
                    nearest_digit = digit
                    nearest_digit_pos = (x, y)
        
        # âœ… Add this safeguard
        if nearest_digit is None:
            nearest_digit = 0
        
        if nearest_digit_pos:
            used_digits.add(nearest_digit_pos)


        min_x = min(p[0] for p in pattern)
        max_x = max(p[0] for p in pattern)
        min_y = min(p[1] for p in pattern)
        max_y = max(p[1] for p in pattern)

        cropped = []
        for x in range(min_x, max_x + 1):
            row = []
            for y in range(min_y, max_y + 1):
                if (x, y) in pattern_set:
                    row.append(nearest_digit)
                else:
                    row.append(0)
            cropped.append(row)

        cropped_patterns.append(cropped)
        pattern_positions.append((min_x, min_y))

    combined = list(zip(cropped_patterns, pattern_positions))
    combined.sort(key=lambda x: (x[1][0], x[1][1]))

    if len(pattern_positions) < 2:
        result = cropped_patterns[0] if cropped_patterns else []
    else:
        row_diff = abs(pattern_positions[0][0] - pattern_positions[1][0])
        col_diff = abs(pattern_positions[0][1] - pattern_positions[1][1])

        if row_diff <= col_diff:
            result = []
            max_height = max(len(p) for p, _ in combined)
            padded_patterns = []
            for p, _ in combined:
                width = len(p[0])
                height = len(p)
                padded = p + [[0] * width for _ in range(max_height - height)]
                padded_patterns.append(padded)

            for row_parts in zip(*padded_patterns):
                row = []
                for part in row_parts:
                    row.extend(part)
                result.append(row)
        else:
            result = []
            max_width = max(len(p[0]) for p, _ in combined)
            for p, _ in combined:
                width = len(p[0])
                padded = [row + [0] * (max_width - width) for row in p]
                result.extend(padded)

    # Final trimming: Find the rightmost non-zero column globally
    if result:
        max_col = max(
            (idx for row in result for idx, val in enumerate(row) if val != 0),
            default=-1
        )
        result = [row[:max_col + 1] for row in result]

    return np.array(result)

#find 5x5

from collections import deque, Counter

def extract_dominant_blocks_with_foreign_digits(grid, background_digits={0}):
    grid = np.array(grid)
    rows, cols = grid.shape
    visited = np.zeros_like(grid, dtype=bool)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    result = []

    for i in range(rows):
        for j in range(cols):
            if visited[i, j] or grid[i, j] in background_digits:
                continue

            digit = grid[i, j]
            queue = deque()
            queue.append((i, j))
            visited[i, j] = True

            min_row, max_row = i, i
            min_col, max_col = j, j
            positions = []

            while queue:
                x, y = queue.popleft()
                positions.append((x, y))

                min_row = min(min_row, x)
                max_row = max(max_row, x)
                min_col = min(min_col, y)
                max_col = max(max_col, y)

                for dx, dy in directions:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < rows and 0 <= ny < cols and not visited[nx, ny] and grid[nx, ny] == digit:
                        queue.append((nx, ny))
                        visited[nx, ny] = True

            block = grid[min_row:max_row+1, min_col:max_col+1]
            flat_block = block.flatten()
            digit_counts = Counter(flat_block)

            # If block contains other digits besides the dominant digit
            if len(digit_counts) > 1:
                dominant_digit = digit_counts.most_common(1)[0][0]
                result.append(dominant_digit)

    return [result]
    
def find_5x5(grid):
    grid = np.array(grid)

    # Step 1: Remove separator columns (columns where all elements are 6)
    cols_to_keep = [i for i in range(grid.shape[1]) if not np.all(grid[:, i] == 6)]
    cleaned_grid = grid[:, cols_to_keep]

    # Step 2: Validate that the cleaned grid now has exactly 15 columns (3 blocks of 5x5)
    if cleaned_grid.shape[1] != 15:
        # Instead of raising error, return None to safely skip this grid
        return None, None, None

    # Step 3: Extract the three 5x5 blocks (row and column ranges)
    left_block = cleaned_grid[0:5, 0:5].tolist()
    middle_block = cleaned_grid[0:5, 5:10].tolist()
    right_block = cleaned_grid[0:5, 10:15].tolist()

    return left_block, middle_block, right_block

def find_pat(block):
    """
    Extracts the pattern from a 5x5 block by keeping rows that contain at least one non-background element (not 7).
    """
    pattern = []
    for row in block:
        if any(cell != 7 for cell in row):
            pattern.append(row[:])  # Keep the entire row as it is

    return pattern

def merge_pat(left, middle, right):
    # Extract patterns
    l = find_pat(left)
    m = find_pat(middle)
    r = find_pat(right)

    # Join in order: Right (top), Middle (middle), Left (bottom)
    combined = r + m + l

    # If combined has less than 5 rows, add rows of 7s on top
    while len(combined) < 5:
        combined = [[7, 7, 7, 7, 7]] + combined  # Add a row on top

    # If combined has more than 5 rows, keep only the last 5 rows
    if len(combined) > 5:
        combined = combined[-5:]  # Take the last 5 rows

    return combined
