import numpy as np

def get_nonzero_bbox(grid):
    """Returns the bounding box of non-zero elements (top, left, bottom, right)."""
    grid = np.array(grid)

    if grid.ndim != 2 or grid.size == 0:
        return 0, 0, 0, 0  # Fallback for invalid input

    rows, cols = np.where(grid != 0)

    if len(rows) == 0 or len(cols) == 0:
        return 0, 0, 0, 0  # No non-zero values

    return rows.min(), cols.min(), rows.max(), cols.max()


def extract_top_left_block(grid, block_size=(3, 3), offset=(0, 0)):
    """Extracts a block from a grid starting at a given offset from the bounding box top-left."""
    top, left, _, _ = get_nonzero_bbox(grid)
    r, c = top + offset[0], left + offset[1]
    return [row[c:c+block_size[1]] for row in grid[r:r+block_size[0]]]

def infer_offset_from_train(train_data):
    """Infers the offset (delta row, delta col) of output relative to object bbox."""
    offsets = []
    for ex in train_data:
        in_grid, out_grid = np.array(ex["input"]), np.array(ex["output"])
        top, left, _, _ = get_nonzero_bbox(in_grid)
        for dr in range(-2, 3):
            for dc in range(-2, 3):
                try:
                    block = in_grid[top+dr:top+dr+3, left+dc:left+dc+3]
                    if block.shape == (3, 3) and np.array_equal(block, out_grid):
                        offsets.append((dr, dc))
                except:
                    continue
    if offsets:
        return offsets[0]  # Use first found valid offset
    return (0, 0)  # Fallback

def modern(train_inputs, train_outputs, test_inputs, block_size=(3, 3)):
    
    train_data = [{"input": inp, "output": out} for inp, out in zip(train_inputs, train_outputs)]
    offset = infer_offset_from_train(train_data)

    results = []
    for i, test_in in enumerate(test_inputs):
        block = extract_top_left_block(test_in, block_size=block_size, offset=offset)
        results.append(block)
    return results
    
def extract_bounding_block(pattern_positions):
    rows = [r for r, c in pattern_positions]
    cols = [c for r, c in pattern_positions]
    min_row, max_row = min(rows), max(rows)
    min_col, max_col = min(cols), max(cols)
    return min_row, max_row, min_col, max_col

def get_digit_positions(grid, digits):
    positions = []
    for digit in digits:
        found = False
        for i, row in enumerate(grid):
            for j, val in enumerate(row):
                if val == digit:
                    positions.append((i, j))
                    found = True
                    break
            if found:
                break
    return positions
    
def solving_grid(grid):
    grid = np.array(grid)
    digits = []

    # Find all unique digits except 0 and 1
    for row in grid:
        for val in row:
            if val not in (0, 1) and val not in digits:
                digits.append(val)

    # Step 1: Extract pattern positions
    pattern_positions = extract_pattern(grid)

    if not pattern_positions or not digits:
        return []

    # Step 2: Get bounding box
    min_row, max_row, min_col, max_col = extract_bounding_block(pattern_positions)

    # Step 3: Get positions of digits
    digit_positions = get_digit_positions(grid, digits)

    # Step 4: Determine arrangement
    arrangement = determine_arrangement(digit_positions)

    # Step 5: Create filled blocks based on arrangement
    result = create_filled_blocks(pattern_positions, digits, min_row, min_col, max_row, max_col, arrangement)

    return result
    
def extract_pattern(grid):
    grid = np.array(grid)
    rows, cols = grid.shape
    pattern_positions = []

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                pattern_positions.append((i, j))

    return pattern_positions
    
def determine_arrangement(digit_positions):
    rows = [r for r, c in digit_positions]
    cols = [c for r, c in digit_positions]

    # If the row positions vary more, it's vertical
    if max(rows) - min(rows) >= max(cols) - min(cols):
        return 'vertical'
    else:
        return 'horizontal'

def create_filled_blocks(pattern_positions, digits, min_row, min_col, max_row, max_col, arrangement):
    pattern_height = max_row - min_row + 1
    pattern_width = max_col - min_col + 1

    if arrangement == 'horizontal':
        filled_blocks = []
        for digit in digits:
            block = [[0 for _ in range(pattern_width)] for _ in range(pattern_height)]
            for r, c in pattern_positions:
                block[r - min_row][c - min_col] = digit
            if not filled_blocks:
                filled_blocks = block
            else:
                # Concatenate horizontally
                filled_blocks = [row + block_row for row, block_row in zip(filled_blocks, block)]
        return filled_blocks

    else:  # vertical
        filled_blocks = []
        for digit in digits:
            block = [[0 for _ in range(pattern_width)] for _ in range(pattern_height)]
            for r, c in pattern_positions:
                block[r - min_row][c - min_col] = digit
            filled_blocks.extend(block)  # Stack vertically
        return filled_blocks



