from collections import defaultdict, deque

def find_digitr_positions(grid):
    pos = defaultdict(list)
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            val = grid[r][c]
            if val != 7:
                pos[val].append((r, c))
    return pos

def find_line_type(points):
    rows = [r for r, c in points]
    cols = [c for r, c in points]
    if all(c == cols[0] for c in cols):
        return 'vertical'
    elif all(r == rows[0] for r in rows):
        return 'horizontal'
    elif all(r - c == rows[0] - cols[0] for r, c in points):
        return 'diagonal'
    elif all(r + c == rows[0] + cols[0] for r, c in points):
        return 'anti-diagonal'
    else:
        return 'scatter'

def line_path(points, line_type):
    if line_type == 'vertical':
        c = points[0][1]
        r1, r2 = min(r for r, _ in points), max(r for r, _ in points)
        return {(r, c) for r in range(r1, r2 + 1)}
    elif line_type == 'horizontal':
        r = points[0][0]
        c1, c2 = min(c for _, c in points), max(c for _, c in points)
        return {(r, c) for c in range(c1, c2 + 1)}
    elif line_type == 'diagonal':
        r1, c1 = min(points)
        length = min(len(points), 20)
        return {(r1 + i, c1 + i) for i in range(length) if r1 + i < 16 and c1 + i < 16}
    elif line_type == 'anti-diagonal':
        r1, c1 = min(points)
        length = min(len(points), 20)
        return {(r1 + i, c1 - i) for i in range(length) if r1 + i < 16 and c1 - i >= 0}
    else:
        return set(points)

def build_dependency_graph(grid):
    digit_pos = find_digitr_positions(grid)
    digit_lines = {d: line_path(pos, find_line_type(pos)) for d, pos in digit_pos.items()}
    
    graph = defaultdict(set)
    
    for d1 in digit_lines:
        for d2 in digit_lines:
            if d1 == d2:
                continue
            if digit_lines[d1] & set(digit_pos[d2]):
                graph[d2].add(d1)  # d2 breaks d1â€™s line

    return graph

def topo_sort(graph):
    in_deg = defaultdict(int)
    for u in graph:
        for v in graph[u]:
            in_deg[v] += 1
    
    queue = deque([u for u in graph if in_deg[u] == 0])
    result = []

    while queue:
        node = queue.popleft()
        result.append(node)
        for neighbor in graph[node]:
            in_deg[neighbor] -= 1
            if in_deg[neighbor] == 0:
                queue.append(neighbor)

    # Handle any nodes not in graph (not broken by or breaking anyone)
    all_nodes = set(graph.keys()) | set(v for neighbors in graph.values() for v in neighbors)
    missing = all_nodes - set(result)
    return result + list(missing)

def solve_task(task):
    results = []
    for test_case in task['test']:
        grid = test_case['input']
        graph = build_dependency_graph(grid)
        order = topo_sort(graph)
        results.append([order[::-1]])  # reversed result
    return results

