def try_direct_cnn_prediction(train_inputs, train_outputs, test_in, expected=None, max_epochs=400):
    
    
    import torch
    import torch.nn as nn
    import torch.optim as optim

    def get_max_shape(grids):
        return max(g.shape[0] for g in grids), max(g.shape[1] for g in grids)

    def one_hot(grid, num_classes=10, target_size=(20, 20)):
        h, w = grid.shape
        H, W = target_size
        out = np.zeros((num_classes, H, W), dtype=np.float32)
        for c in range(num_classes):
            mask = (grid == c).astype(np.float32)
            out[c, :h, :w] = mask
        return out

    def pad_grid(grid, target_size):
        h, w = grid.shape
        H, W = target_size
        padded = np.zeros(target_size, dtype=int)
        padded[:h, :w] = grid
        return padded

    # Determine max H, W across inputs and outputs
    all_shapes = [np.array(g).shape for g in train_inputs + train_outputs + [test_in]]
    max_h = max(s[0] for s in all_shapes)
    max_w = max(s[1] for s in all_shapes)
    target_size = (max_h, max_w)

    class SimpleCNN(nn.Module):
        def __init__(self, in_channels=10):
            super().__init__()
            self.net = nn.Sequential(
                nn.Conv2d(in_channels, 32, 3, padding=1),
                nn.ReLU(),
                nn.Conv2d(32, 10, 1)
            )
        def forward(self, x):
            return self.net(x)

    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    model = SimpleCNN().to(device)
    optimizer = optim.Adam(model.parameters(), lr=0.01)
    loss_fn = nn.CrossEntropyLoss()

    # --- Training ---
    model.train()
    for epoch in range(max_epochs):
        for x, y in zip(train_inputs, train_outputs):
            x_arr = one_hot(np.array(x), target_size=target_size)
            y_arr = pad_grid(np.array(y), target_size=target_size)

            x_t = torch.tensor(x_arr).unsqueeze(0).to(device)  # [1, 10, H, W]
            y_t = torch.tensor(y_arr).unsqueeze(0).long().to(device)  # [1, H, W]

            pred = model(x_t)  # [1, 10, H, W]
            loss = loss_fn(pred, y_t)
            optimizer.zero_grad()
            loss.backward()
            optimizer.step()

    # --- Prediction ---
    model.eval()
    with torch.no_grad():
        x_arr = one_hot(np.array(test_in), target_size=target_size)
        x_t = torch.tensor(x_arr).unsqueeze(0).to(device)
        pred_logits = model(x_t)
        pred = torch.argmax(pred_logits, dim=1).squeeze().cpu().numpy()

    # Crop back to original output size
    if expected is not None:
        expected = np.array(expected)
        h, w = expected.shape
        if pred.ndim == 2:
            pred_cropped = pred[:h, :w]
        else:
            print("âš ï¸� Predicted output is not 2D:", pred.shape)
            return None, False

        if np.array_equal(pred_cropped, expected):
            return pred_cropped, True
        return pred_cropped, False
    return pred, False
