import numpy as np

def is_3d(lst):
    return isinstance(lst, list) and len(lst) > 0 and isinstance(lst[0], list) and len(lst[0]) > 0 and isinstance(lst[0][0], list)

def is_valid_block(block, forbidden_val):
    if block.shape != (3, 3):
        return False
    if np.any(block == forbidden_val):
        return False
    for row in block:
        if not any(val != 0 and val != forbidden_val for val in row):
            return False
    return True

def find_full_plus_center(grid):
    grid = np.array(grid)
    for val in np.unique(grid):
        if val == 0:
            continue
        row_indices = np.where(np.all(grid == val, axis=1))[0]
        col_indices = np.where(np.all(grid == val, axis=0))[0]
        for r in row_indices:
            for c in col_indices:
                return r, c, val
    return None

def extract_quadrant_block(grid, r_start, r_end, c_start, c_end, forbidden_val):
    best_block = None
    best_score = -1
    
    for r in range(r_start, r_end - 2):
        for c in range(c_start, c_end - 2):
            block = grid[r:r + 3, c:c + 3]
            if is_valid_block(block, forbidden_val):
                # Score by number of non-zero (excluding forbidden)
                score = np.sum((block != 0) & (block != forbidden_val))
                if score > best_score:
                    best_score = score
                    best_block = block
    return best_block


def extract_blocks_from_full_plus(grid):
    grid = np.array(grid)
    center = find_full_plus_center(grid)
    if center is None:
        # print("â�Œ No full plus center found.")
        return []

    r, c, val = center
    rows, cols = grid.shape
    # print(f"Plus center: ({r},{c}) with value {val}")

    blocks = {}
    blocks['a'] = extract_quadrant_block(grid, 0, r - 1, 0, c - 1, val)  # top-left
    blocks['b'] = extract_quadrant_block(grid, 0, r - 1, c + 1, cols, val)  # top-right
    blocks['c'] = extract_quadrant_block(grid, r + 1, rows, 0, c - 1, val)  # bottom-left
    blocks['d'] = extract_quadrant_block(grid, r + 1, rows, c + 1, cols, val)  # bottom-right

    for k, blk in blocks.items():
        if blk is not None:
            # print(f"âœ… Block {k} extracted.")
            pass
        else:
            # print(f"â�Œ Block {k} not found.")
            pass

    if any(blocks[k] is None for k in ['a', 'b', 'c', 'd']):
        # print("â�Œ Not all valid blocks found.")
        return []

    top_row = np.hstack((blocks['a'], blocks['b']))
    bottom_row = np.hstack((blocks['c'], blocks['d']))
    result = np.vstack((top_row, bottom_row)).tolist()

    # # print("\nâœ… Final Result:")
    # for row in result:
    #     print(row)

    return [result]

