import numpy as np
from scipy.ndimage import label, find_objects

def extract_object_to_position_mapping(input_grid, output_grid):
    input_arr = np.array(input_grid)
    output_arr = np.array(output_grid)

    if input_arr.shape != output_arr.shape:
        return None

    structure = np.ones((3, 3), dtype=int)
    in_lbl, n_in = label(input_arr > 0, structure=structure)
    out_lbl, n_out = label(output_arr > 0, structure=structure)

    if n_in != n_out:
        return None

    in_objs = [input_arr[s] for s in find_objects(in_lbl)]
    out_slices = find_objects(out_lbl)

    placements = []
    for obj, sl_out in zip(in_objs, out_slices):
        shape = obj.shape
        center = ((sl_out[0].start + sl_out[0].stop) // 2,
                  (sl_out[1].start + sl_out[1].stop) // 2)
        placements.append({"shape": shape, "target_center": center})

    return {"type": "object_to_position", "placements": placements}

def extract_color_region_mapping(input_grid, output_grid):
    input_arr = np.array(input_grid)
    output_arr = np.array(output_grid)

    colors = set(np.unique(input_arr)) - {0}
    mappings = []

    for c in colors:
        in_mask = (input_arr == c)
        out_mask = (output_arr == c)
        if np.array_equal(in_mask, out_mask):
            continue
        in_coords = np.argwhere(in_mask)
        out_coords = np.argwhere(out_mask)
        if in_coords.size > 0 and out_coords.size > 0:
            mappings.append({
                "color": c,
                "input_bounds": in_coords,
                "output_bounds": out_coords
            })

    if mappings:
        return {"type": "color_region_mapping", "mappings": mappings}
    return None

def extract_repeat_pattern_rule(input_grid, output_grid):
    input_arr = np.array(input_grid)
    output_arr = np.array(output_grid)

    ih, iw = input_arr.shape
    oh, ow = output_arr.shape

    if oh % ih == 0 and ow % iw == 0:
        reps_y, reps_x = oh // ih, ow // iw
        tiled = np.tile(input_arr, (reps_y, reps_x))
        if np.array_equal(tiled, output_arr):
            return {"type": "tiled_repeat", "repeat": (reps_y, reps_x)}

    return None

def try_structural_pattern_matchers(train_in, train_out, test_in):
    """
    Try to extract a structural transformation rule from train and apply to test.
    """

    # 1. Try tiled repetition
    rule = extract_repeat_pattern_rule(train_in, train_out)
    if rule and rule["type"] == "tiled_repeat":
        reps = rule["repeat"]
        return np.tile(np.array(test_in), reps).tolist()

    # 2. Try color region mapping
    rule = extract_color_region_mapping(train_in, train_out)
    if rule and rule["type"] == "color_region_mapping":
        result = np.zeros_like(test_in)
        for mapping in rule["mappings"]:
            color = mapping["color"]
            mask = (np.array(test_in) == color)
            coords = np.argwhere(mask)
            if coords.size == 0:
                continue
            offset = mapping["output_bounds"].mean(axis=0) - mapping["input_bounds"].mean(axis=0)
            offset = np.round(offset).astype(int)
            for y, x in coords:
                ny, nx = y + offset[0], x + offset[1]
                if 0 <= ny < result.shape[0] and 0 <= nx < result.shape[1]:
                    result[ny, nx] = color
        return result.tolist()

    # 3. Try object to position mapping
    rule = extract_object_to_position_mapping(train_in, train_out)
    if rule and rule["type"] == "object_to_position":
        input_arr = np.array(test_in)
        result = np.zeros_like(input_arr)
        structure = np.ones((3, 3), dtype=int)
        labeled, n = label(input_arr > 0, structure=structure)
        objects = find_objects(labeled)

        for i, placement in enumerate(rule["placements"]):
            sl = objects[i]
            obj = input_arr[sl]
            h, w = obj.shape
            center_y, center_x = placement["target_center"]
            top = max(0, center_y - h // 2)
            left = max(0, center_x - w // 2)
            bottom = min(result.shape[0], top + h)
            right = min(result.shape[1], left + w)
            result[top:bottom, left:right] = obj[:bottom-top, :right-left]
        return result.tolist()

    return None  # No rule matched

