from collections import defaultdict
import numpy as np

def extract_dominant_shape_and_repeat(input_grid, output_grid):
    comps = extract_connected_components(input_grid, bg_color=0)

    shape_counts = defaultdict(int)
    shape_to_mask = {}

    for color, pixels in comps:
        ys, xs = zip(*pixels)
        y0, y1 = min(ys), max(ys)+1
        x0, x1 = min(xs), max(xs)+1

        mask = np.zeros((y1 - y0, x1 - x0), dtype=int)
        for y, x in pixels:
            mask[y - y0][x - x0] = 1

        flat_shape = tuple(mask.flatten())
        shape_counts[flat_shape] += 1
        shape_to_mask[flat_shape] = mask

    if not shape_counts:
        return None

    dominant_shape = max(shape_counts, key=shape_counts.get)
    dominant_mask = shape_to_mask[dominant_shape]

    return {
        "type": "dominant_shape_repeat",
        "dominant_mask": dominant_mask.tolist(),
        "count": shape_counts[dominant_shape]
    }


def apply_dominant_shape_repeat_rule(test_grid, rule, color=8):
    grid = np.array(test_grid)
    h, w = grid.shape
    mask = np.array(rule["dominant_mask"])
    mh, mw = mask.shape
    count = rule.get("count", 1)

    out = np.zeros_like(grid)

    placed = 0
    for i in range(0, h - mh + 1):
        for j in range(0, w - mw + 1):
            if placed >= count:
                break
            # Place mask with color
            for dy in range(mh):
                for dx in range(mw):
                    if mask[dy][dx] == 1:
                        out[i + dy][j + dx] = color
            placed += 1
        if placed >= count:
            break

    return out.tolist()

def detect_color_split_regions(grid):
    """
    Detects vertical/horizontal zones split by color.
    Useful when transformation depends on spatial color logic.
    """
    arr = np.array(grid)
    h, w = arr.shape

    # Check if rows/columns contain mostly 1 color
    row_zones = [len(set(arr[y, :])) == 1 for y in range(h)]
    col_zones = [len(set(arr[:, x])) == 1 for x in range(w)]

    if sum(row_zones) >= h // 2 or sum(col_zones) >= w // 2:
        return {
            "type": "color_split",
            "direction": "horizontal" if sum(row_zones) > sum(col_zones) else "vertical"
        }
    return None
def detect_grid_symmetry(grid):
    """
    Returns type of symmetry if found (horizontal/vertical/diagonal/anti-diagonal)
    """
    arr = np.array(grid)
    if np.array_equal(arr, np.flipud(arr)):
        return "horizontal"
    elif np.array_equal(arr, np.fliplr(arr)):
        return "vertical"
    elif np.array_equal(arr, arr.T):
        return "diagonal"
    elif np.array_equal(arr, np.fliplr(np.flipud(arr.T))):
        return "anti-diagonal"
    return None


def detect_color_block_count(grid):
    """
    Counts number of connected components per color.
    """
    arr = np.array(grid)
    comps = extract_connected_components(arr)
    color_counts = defaultdict(int)
    for comp in comps:
        color_counts[comp["color"]] += 1
    return dict(color_counts)

