def detect_shape_color_swap_fuzzy(input_grid, output_grid, bg_color=0):
    from collections import defaultdict, Counter
    import numpy as np

    def shape_signature(pixels):
        min_y = min(y for y, x in pixels)
        min_x = min(x for y, x in pixels)
        norm = [(y - min_y, x - min_x) for y, x in pixels]
        max_y = max(y for y, x in norm)
        max_x = max(x for y, x in norm)
        mask = np.zeros((max_y+1, max_x+1), dtype=int)
        for y, x in norm:
            mask[y][x] = 1
        return str(mask.tolist())

    in_components = extract_connected_components(input_grid, bg_color)
    out_components = extract_connected_components(output_grid, bg_color)

    in_shapes = defaultdict(list)
    out_shapes = defaultdict(list)

    for color, pixels in in_components:
        sig = shape_signature(pixels)
        in_shapes[sig].append(color)

    for color, pixels in out_components:
        sig = shape_signature(pixels)
        out_shapes[sig].append(color)

    color_map = {}
    for sig in in_shapes:
        if sig in out_shapes:
            in_common = in_shapes[sig]
            out_common = out_shapes[sig]
            for c_in, c_out in zip(in_common, out_common):
                color_map[c_in] = c_out

    return color_map if color_map else None

def apply_shape_preserving_color_swap(grid, color_map):
    h, w = len(grid), len(grid[0])
    out = [[0]*w for _ in range(h)]

    for color, pixels in extract_connected_components(grid):
        new_color = color_map.get(color, color)
        for y, x in pixels:
            out[y][x] = new_color
    return out

def extract_normalized_object_shapes(grid, bg_color=0):
    shapes = []
    components = extract_connected_components(grid, bg_color)

    for color, pixels in components:
        min_y = min(y for y, x in pixels)
        min_x = min(x for y, x in pixels)
        shape = sorted((y - min_y, x - min_x) for y, x in pixels)
        shapes.append((color, shape))
    return shapes

def infer_color_map_and_repeat_ratio(train_input, train_output):
    from collections import Counter
    from math import ceil

    h_in, h_out = len(train_input), len(train_output)
    repeat_ratio = h_out / h_in

    # Infer color map: count frequencies
    input_counts = Counter(cell for row in train_input for cell in row)
    output_counts = Counter(cell for row in train_output for cell in row)

    # Simple greedy matching by highest frequency
    color_map = {}
    for (in_color, _), (out_color, _) in zip(input_counts.most_common(), output_counts.most_common()):
        color_map[in_color] = out_color

    return color_map, repeat_ratio

def smart_row_repeat_solver(train_input, train_output, test_input):
    color_map, repeat_ratio = infer_color_map_and_repeat_ratio(train_input, train_output)

    def solve(input_grid):
        h, w = len(input_grid), len(input_grid[0])

        mapped = [[color_map.get(cell, cell) for cell in row] for row in input_grid]

        output_h = ceil(h * repeat_ratio)
        full_repeats = output_h // h
        remainder = output_h % h

        output = []
        for _ in range(full_repeats):
            output.extend(mapped)
        output.extend(mapped[:remainder])
        return output

    return solve(test_input)

def detect_repeat_axis(train_input, train_output):
    if len(train_output) > len(train_input):
        return 'row'
    elif len(train_output[0]) > len(train_input[0]):
        return 'col'
    return 'none'

