def extract_and_cluster_shapes_by_structure(grid, bg_color=0):
    from collections import defaultdict
    import numpy as np

    components = extract_connected_components(grid, bg_color)
    clusters = defaultdict(list)

    for color, pixels in components:
        min_y = min(y for y, x in pixels)
        min_x = min(x for y, x in pixels)
        shape = [(y - min_y, x - min_x) for y, x in pixels]
        shape_arr = np.zeros((max(y for y, x in shape)+1, max(x for y, x in shape)+1), dtype=int)
        for y, x in shape:
            shape_arr[y][x] = 1
        key = str(shape_arr)
        clusters[key].append((color, pixels))
    
    return list(clusters.values())
    
def compare_component_distributions(input_grid, output_grid, bg_color=0):
    in_clusters = extract_and_cluster_shapes_by_structure(input_grid, bg_color)
    out_clusters = extract_and_cluster_shapes_by_structure(output_grid, bg_color)
    
    in_counts = [len(c) for c in in_clusters]
    out_counts = [len(c) for c in out_clusters]
    
    return in_counts, out_counts

def extract_object_positions_and_colors(grid, bg_color=0):
    components = extract_connected_components(grid, bg_color)
    objects = []

    for color, pixels in components:
        y_avg = sum(y for y, x in pixels) / len(pixels)
        x_avg = sum(x for y, x in pixels) / len(pixels)
        objects.append({"pos": (round(y_avg), round(x_avg)), "color": color, "pixels": pixels})
    
    return objects

def visual_transform_detector(input_grid, output_grid, bg_color=0):
    in_objs = extract_object_positions_and_colors(input_grid, bg_color)
    out_objs = extract_object_positions_and_colors(output_grid, bg_color)

    if len(in_objs) != len(out_objs):
        return None

    deltas = []
    color_map = {}

    for i, (in_obj, out_obj) in enumerate(zip(in_objs, out_objs)):
        dy = out_obj["pos"][0] - in_obj["pos"][0]
        dx = out_obj["pos"][1] - in_obj["pos"][1]
        deltas.append((dy, dx))
        color_map[in_obj["color"]] = out_obj["color"]

    # Check if consistent spatial shift
    consistent = all(d == deltas[0] for d in deltas)
    if consistent:
        return {"shift": deltas[0], "color_map": color_map}
    return None
    
def apply_visual_shift_and_color_map(grid, transform, bg_color=0):
    h, w = len(grid), len(grid[0])
    out_grid = [[bg_color]*w for _ in range(h)]
    dy, dx = transform["shift"]
    cmap = transform["color_map"]

    for color, pixels in extract_connected_components(grid, bg_color):
        new_color = cmap.get(color, color)
        for y, x in pixels:
            ny, nx = y + dy, x + dx
            if 0 <= ny < h and 0 <= nx < w:
                out_grid[ny][nx] = new_color
    return out_grid

