import numpy as np
def transform_grid(grid):
    grid = np.array(grid)
    colored_cells = []

    # Step 1: Find all colored (non-zero, non-3) cells
    for r in range(grid.shape[0]):
        for c in range(grid.shape[1]):
            val = grid[r, c]
            if val != 0 and val != 3:
                colored_cells.append(val)

    if not colored_cells:
        return [grid.tolist()]

    # Step 2: Determine output size
    out_w = len(colored_cells) * 4  # each cell takes 4 cols
    out_h = len(colored_cells) * 4  # each cell takes 3 rows + 1 spacer

    canvas = np.zeros((out_h, out_w), dtype=int)

    # Step 3: Paint each colored cell at a unique horizontal block
    for idx, val in enumerate(colored_cells):
        row_ptr = idx * 4
        col_ptr = idx * 4

        row = [0] * out_w
        row[col_ptr] = val

        canvas[row_ptr] = row
        canvas[row_ptr + 1] = [3] * out_w
        canvas[row_ptr + 2] = row
        # row_ptr + 3 stays zero (spacer)

    return [canvas.tolist()]
    
def is_road_like_grid(grid, threshold=0.5):
    """
    Returns True if a dominant 'road' color appears in multiple rows/columns.
    """
    grid = np.array(grid)
    h, w = grid.shape
    color_scores = Counter()

    # Check rows
    for row in grid:
        for color in set(row):
            if color != 0 and (row == color).sum() / w >= threshold:
                color_scores[color] += 1

    # Check columns
    for x in range(w):
        col = grid[:, x]
        for color in set(col):
            if color != 0 and (col == color).sum() / h >= threshold:
                color_scores[color] += 1

    if not color_scores:
        return False

    # At least 2 lines (row+col) dominated by same color
    most_common_count = color_scores.most_common(1)[0][1]
    return most_common_count >= 2

def road_color_prediction(grid):
    grid = np.array(grid)
    
    # Step 1: Detect road color
    road_color = detect_road_color(grid)
    if road_color is None:
        return grid.tolist()  # Fallback: return original grid
    
    # Step 2: Get foreground mask (excluding road and 0)
    object_mask = extract_foreground_mask(grid, exclude_colors={road_color, 0})

    # Step 3: Extract components using the mask
    labeled, num_features = label(object_mask)
    slices = find_objects(labeled)
    components = []
    for i, sl in enumerate(slices):
        y0, y1 = sl[0].start, sl[0].stop
        x0, x1 = sl[1].start, sl[1].stop
        subgrid = grid[y0:y1, x0:x1]
        component = np.where(labeled[y0:y1, x0:x1] == (i + 1), subgrid, 0)
        components.append((component.tolist(), y0, x0))

    if not components:
        return [[0]]  # Empty case

    # Step 4: Sort components
    sorted_components = sort_components_by_position(components)

    # Step 5: Decide layout
    layout = choose_layout(sorted_components)

    # Step 6: Pack based on layout
    if layout == "horizontal_pack":
        output = pack_components_into_output(sorted_components)
    elif layout == "vertical_pack":
        output = pack_components_vertically(sorted_components)
    else:
        output = pack_components_into_output(sorted_components)  # Fallback

    return output
def road_color_prediction_multi(grid):
    grid = np.array(grid)
    road_colors = detect_multiple_road_colors(grid)
    if not road_colors:
        return [[0]]

    all_components = []

    for rc in road_colors:
        mask = extract_foreground_mask(grid, exclude_colors={0, rc})
        labeled, _ = label(mask)
        slices = find_objects(labeled)
        for i, sl in enumerate(slices):
            y0, y1 = sl[0].start, sl[0].stop
            x0, x1 = sl[1].start, sl[1].stop
            subgrid = grid[y0:y1, x0:x1]
            component = np.where(labeled[y0:y1, x0:x1] == (i + 1), subgrid, 0)
            all_components.append((component.tolist(), y0, x0))

    if not all_components:
        return [[0]]

    sorted_components = sort_components_by_position(all_components)
    return pack_components_into_output(sorted_components)


import numpy as np
from collections import Counter

def detect_road_color(grid, min_fraction=0.5):
    grid = np.array(grid)
    h, w = grid.shape
    scores = Counter()

    for y in range(h):
        row = grid[y]
        for color in set(row):
            if color == 0:
                continue
            if np.sum(row == color) >= min_fraction * w:
                scores[color] += 1

    for x in range(w):
        col = grid[:, x]
        for color in set(col):
            if color == 0:
                continue
            if np.sum(col == color) >= min_fraction * h:
                scores[color] += 1

    if not scores:
        return None

    return scores.most_common(1)[0][0]

def detect_multiple_road_colors(grid, min_fraction=0.5):
    grid = np.array(grid)
    h, w = grid.shape
    possible_colors = Counter()

    for y in range(h):
        row = grid[y]
        for color in set(row):
            if color == 0: continue
            if np.sum(row == color) >= min_fraction * w:
                possible_colors[color] += 1

    for x in range(w):
        col = grid[:, x]
        for color in set(col):
            if color == 0: continue
            if np.sum(col == color) >= min_fraction * h:
                possible_colors[color] += 1

    return [c for c, _ in possible_colors.most_common()]


def sort_components(components, strategy="by_color_then_position"):
    def get_main_color(comp):
        flat = [val for row in comp[0] for val in row if val != 0]
        return Counter(flat).most_common(1)[0][0] if flat else 0
    
    if strategy == "by_color_then_position":
        return sorted(components, key=lambda x: (get_main_color(x), x[1], x[2]))
    elif strategy == "by_row_then_col":
        return sorted(components, key=lambda x: (x[1], x[2]))
    else:
        return components

def arrange_components(components, layout="horizontal_pack", max_width=None):
    if layout == "horizontal_pack":
        return pack_components_into_output(components, row_width=max_width)
    elif layout == "vertical_pack":
        return pack_components_vertically(components)
    elif layout == "grid_pack":
        return pack_in_grid(components)
    else:
        raise ValueError("Unknown layout:", layout)
def pack_components_vertically(components):
    out_w = max(len(c[0][0]) for c in components)
    out_h = sum(len(c[0]) for c in components)
    output = [[0] * out_w for _ in range(out_h)]

    y = 0
    for comp, _, _ in components:
        h, w = len(comp), len(comp[0])
        for dy in range(h):
            for dx in range(w):
                if comp[dy][dx] != 0:
                    output[y + dy][dx] = comp[dy][dx]
        y += h
    return output

def solidfill(test_in):
    result = extract_all_blocks(test_in)

    if len(result) == 2:
        a, b = result
        filled_grid = fill_grid_by_rules_dynamic(a,b)
        return filled_grid
        
def choose_layout(components):
    heights = [len(c[0]) for c in components]
    widths = [len(c[0][0]) for c in components]
    avg_h, avg_w = np.mean(heights), np.mean(widths)

    if len(components) <= 2:
        return "horizontal_pack"
    if avg_h > avg_w * 1.2:
        return "vertical_pack"
    if avg_w > avg_h * 1.2:
        return "horizontal_pack"
    return "grid_pack"
def pack_in_grid(components, cols=None):
    if not components:
        return [[0]]

    if cols is None:
        cols = int(np.ceil(np.sqrt(len(components))))
    rows = int(np.ceil(len(components) / cols))

    cell_heights = [len(c[0]) for c in components]
    cell_widths = [len(c[0][0]) for c in components]
    max_h, max_w = max(cell_heights), max(cell_widths)

    grid_h = rows * max_h
    grid_w = cols * max_w
    output = [[0] * grid_w for _ in range(grid_h)]

    for i, (comp, _, _) in enumerate(components):
        row = i // cols
        col = i % cols
        for y in range(len(comp)):
            for x in range(len(comp[0])):
                if comp[y][x] != 0:
                    output[row * max_h + y][col * max_w + x] = comp[y][x]

    return output


def extract_foreground_mask(grid, exclude_colors={0}):
    grid = np.array(grid)
    mask = np.ones_like(grid, dtype=bool)
    for color in exclude_colors:
        mask &= (grid != color)
    return mask

from scipy.ndimage import label, find_objects

def extract_non_road_components(grid, exclude):
    """
    Extract connected components excluding the given color (e.g., road color).
    Returns list of (subgrid, top-left y, top-left x).
    """
    grid = np.array(grid)
    mask = (grid != exclude) & (grid != 0)
    labeled, num_features = label(mask)
    slices = find_objects(labeled)

    components = []
    for i, sl in enumerate(slices):
        y0, y1 = sl[0].start, sl[0].stop
        x0, x1 = sl[1].start, sl[1].stop
        subgrid = grid[y0:y1, x0:x1]
        component = np.where(labeled[y0:y1, x0:x1] == (i + 1), subgrid, 0)
        components.append((component.tolist(), y0, x0))

    return components
def sort_components_by_position(components):
    # Add average color value for grouping by color
    def get_main_color(comp):
        flat = [val for row in comp[0] for val in row if val != 0]
        return Counter(flat).most_common(1)[0][0] if flat else 0

    return sorted(components, key=lambda x: (get_main_color(x), x[1], x[2]))

def pack_components_into_output(components, row_width=None):
    if not components:
        return []  # Or return [[0]] to keep it a 2D shape

    rows = []
    current_row = []
    current_width = 0
    max_height = 0

    for comp, _, _ in components:
        h, w = len(comp), len(comp[0])
        if row_width and current_width + w > row_width:
            rows.append((current_row, max_height))
            current_row = []
            current_width = 0
            max_height = 0
        current_row.append(comp)
        current_width += w
        max_height = max(max_height, h)

    if current_row:
        rows.append((current_row, max_height))

    # Handle case where all rows are empty
    if not rows:
        return []

    out_h = sum(height for _, height in rows)
    out_w = max((sum(len(comp[0]) for comp in row) for row, _ in rows), default=1)
    output = [[0 for _ in range(out_w)] for _ in range(out_h)]

    y = 0
    for row, height in rows:
        x = 0
        for comp in row:
            for dy, row_data in enumerate(comp):
                for dx, val in enumerate(row_data):
                    if val != 0:
                        output[y + dy][x + dx] = val
            x += len(comp[0])
        y += height

    return output

