def try_color_histogram_count(grid, expected):
    unique, counts = np.unique(grid, return_counts=True)
    histogram = list(zip(unique, counts))
    histogram = [item for item in histogram if item[0] != 0]  # exclude background

    output = np.array([[color, count] for color, count in sorted(histogram)])
    if compare(output.tolist(), expected):
        return output, "color histogram count"
    return None, None
    
def try_one_hot_color_encoding(grid, expected):
    colors = set(np.unique(grid)) - {0}
    if not colors:
        return None, None

    h, w = grid.shape
    output = []
    for color in colors:
        layer = np.zeros((h, w), dtype=int)
        layer[grid == color] = color
        output.append(layer)

    if not output:
        return None, None

    try:
        stacked = np.stack(output, axis=0)  # Shape: (num_colors, h, w)
    except ValueError:
        return None, None

    # Try projecting all layers (OR-like composite)
    projection = np.max(stacked, axis=0)
    if compare(projection.tolist(), expected):
        return projection, "one-hot color projection"

    # Try checking individual layers
    for i, layer in enumerate(output):
        if compare(layer.tolist(), expected):
            return layer, f"single color layer {list(colors)[i]}"

    return None, None

def try_rearranged_blocks(regions, expected):
    from itertools import permutations

    if len(regions) > 5:
        return None, None  # too slow otherwise

    blocks = [r["grid"] for r in regions]

    # Try sorted horizontal/vertical first
    try:
        h_out = np.hstack(blocks)
        if compare(h_out.tolist(), expected):
            return h_out, "sorted blocks horizontally"
        v_out = np.vstack(blocks)
        if compare(v_out.tolist(), expected):
            return v_out, "sorted blocks vertically"
    except:
        pass

    # Try all permutations (limited)
    for perm in permutations(blocks):
        try:
            h_out = np.hstack(perm)
            if compare(h_out.tolist(), expected):
                return h_out, "rearranged blocks horizontally"
            v_out = np.vstack(perm)
            if compare(v_out.tolist(), expected):
                return v_out, "rearranged blocks vertically"
        except:
            continue
    return None, None


def try_compress_nonzero_bbox(grid, expected):
    if not np.any(grid):  # all zeros
        return None, None
    coords = np.argwhere(grid > 0)
    minr, minc = coords.min(axis=0)
    maxr, maxc = coords.max(axis=0) + 1
    if (minr == 0 and minc == 0 and maxr == grid.shape[0] and maxc == grid.shape[1]):
        return None, None  # no cropping needed
    cropped = grid[minr:maxr, minc:maxc]
    if compare(cropped.tolist(), expected):
        return cropped, "cropped nonzero bounding box"
    return None, None


def try_extract_largest_region_by_color(regions, expected):
    if not regions:
        return None, None
    largest = max(regions, key=lambda r: r["grid"].size)
    if compare(largest["grid"].tolist(), expected):
        return largest["grid"], f"largest region of color {largest['color']}"
    return None, None

def try_sort_blocks_by_position(regions, expected):
    blocks = sorted(regions, key=lambda r: (r["bbox"][0], r["bbox"][1]))  # sort by top-left
    try:
        output = np.hstack([r["grid"] for r in blocks])
        if compare(output.tolist(), expected):
            return output, "sorted blocks by position"
    except:
        pass
    return None, None

# === Function: Count Block Grid Size ===
def count_block_grid_size(grid2d, min_frac=0.1):
    grid = np.array(grid2d)
    H, W = grid.shape
    mask = ~np.isin(grid, list(BACKGROUND_IDS))
    
    labeled, _ = label(mask)
    slices = find_objects(labeled)
    
    block_rows = set()
    block_cols = set()

    for sl in slices:
        if sl is None:
            continue
        
        minr, maxr = sl[0].start, sl[0].stop - 1
        minc, maxc = sl[1].start, sl[1].stop - 1
        h, w = maxr - minr + 1, maxc - minc + 1

        if h < H * min_frac or w < W * min_frac:
            continue

        cy = (minr + maxr) // 2
        cx = (minc + maxc) // 2

        block_rows.add(int(cy // (H / 4)))
        block_cols.add(int(cx // (W / 3)))

    # Ensure at least 1x1 is returned to avoid ZeroDivisionError
    return max(len(block_rows), 1), max(len(block_cols), 1)

# === Function: Summarize Grid by Blocks ===
def summarize_by_block(grid2d, m, n):
    if grid2d is None or grid2d.size == 0:
        raise ValueError("Empty or invalid grid passed to summarize_by_block")

    H, W = len(grid2d), len(grid2d[0])
    if m == 0 or n == 0:
        raise ValueError(f"Invalid block shape: m={m}, n={n}")
    
    bs = H // m  # block height
    bw = W // n  # block width
    out = []

    for bi in range(m):
        row = []
        for bj in range(n):
            block = [grid2d[bi*bs + i][bj*bw : (bj+1)*bw] for i in range(bs)]
            flat = [val for subrow in block for val in subrow]
            flat = [val for val in flat if val not in BACKGROUND_IDS]
            if not flat:
                row.append(0)
            else:
                mode_val = mode(flat, keepdims=False).mode
                row.append(int(mode_val))
        out.append(row)

    return out

def get_background_colors(grid, top_n=2):
    c = Counter(np.array(grid).flatten())
    return set([color for color, _ in c.most_common(top_n)])

def extract_blocks(grid):
    grid = np.array(grid)
    background = get_background_colors(grid, top_n=2)
    mask = ~np.isin(grid, list(background))
    labeled, _ = nd_label(mask)

    blocks = []
    for r in regionprops(labeled):
        minr, minc, maxr, maxc = r.bbox
        subgrid = grid[minr:maxr, minc:maxc]
        unique = set(subgrid.flatten()) - background
        if len(unique) == 1:
            blocks.append((unique.pop(), r.centroid))

    return blocks

def build_output_grid(blocks):
    blocks = sorted(blocks, key=lambda x: (int(round(x[1][0])), int(round(x[1][1]))))
    colors = [c for c, _ in blocks]
    n = len(colors)
    for r in range(int(n**0.5), 0, -1):
        if n % r == 0:
            rows, cols = r, n // r
            return np.array(colors).reshape((rows, cols)).tolist()
    return [colors]  # fallback: 1-row grid

