def try_stack_normalized_blocks_vertically(regions, expected):
    blocks = []
    max_h, max_w = 0, 0
    for region in regions:
        block = region["grid"]
        if block.size == 0:  # Skip empty blocks
            continue
        max_h = max(max_h, block.shape[0])
        max_w = max(max_w, block.shape[1])
        blocks.append(block)

    if not blocks:  # Nothing to stack
        return None, None

    padded_blocks = []
    for block in blocks:
        padded = np.full((max_h, max_w), 0)
        h, w = block.shape
        padded[:h, :w] = block
        padded_blocks.append(padded)

    output = np.vstack(padded_blocks)
    if compare(output.tolist(), expected):
        return output, "stacked vertically normalized blocks"
    return None, None


