import matplotlib.pyplot as plt
def plot_grids(predicted_grid, expected_grid, task_id):
    grids = [predicted_grid, expected_grid]
    titles = ['Predicted', 'Expected']
    
    fig, axes = plt.subplots(1, 2, figsize=(6, 3))
    
    for ax, title, grid in zip(axes, titles, grids):
        arr = np.array(grid)
        if arr.dtype == object:
            arr = arr.astype(int)  # Force convert to int
        ax.imshow(arr, cmap="tab20", interpolation="none")
        ax.set_title(title)
        ax.axis("off")

    fig.suptitle(f"Task: {task_id}", fontsize=12)
    plt.tight_layout()
    plt.show()
    
import numpy as np

def crop_component(pixels, grid):
    h, w = len(grid), len(grid[0])
    temp_grid = [[0]*w for _ in range(h)]
    color = grid[pixels[0][0]][pixels[0][1]]
    for y, x in pixels:
        temp_grid[y][x] = color

    arr = np.array(temp_grid)
    ys, xs = np.where(arr != 0)
    y0, y1 = ys.min(), ys.max() + 1
    x0, x1 = xs.min(), xs.max() + 1
    return arr[y0:y1, x0:x1]

def get_variants(arr):
    variants = []
    for k in range(4):
        rot = np.rot90(arr, k)
        variants.append(rot)
        variants.append(np.fliplr(rot))
        variants.append(np.flipud(rot))
    return variants

# === Main generalized shapeâ†’color remapper ===
def generalize_shape_to_color_mapping(input_grid):
    components = extract_connected_components(input_grid, bg_color=0)

    shape_to_color = {}
    color_id = 1
    output_grid = [[0]*len(components)]

    seen_shapes = []

    for i, (color, pixels) in enumerate(components):
        shape = crop_component(pixels, input_grid)
        variants = get_variants(shape)

        matched = False
        for known_shape in seen_shapes:
            if any(np.array_equal(v, known_shape) for v in variants):
                matched = True
                output_grid[0][i] = shape_to_color[known_shape.tobytes()]
                break

        if not matched:
            seen_shapes.append(shape)
            shape_to_color[shape.tobytes()] = color_id
            output_grid[0][i] = color_id
            color_id += 1

    return output_grid
    
from collections import deque
def extract_connected_components(grid, bg_color=None):
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]
    components = []

    for i in range(h):
        for j in range(w):
            if visited[i][j] or grid[i][j] == bg_color:
                continue
            color = grid[i][j]
            q = deque([(i, j)])
            component = []

            while q:
                x, y = q.popleft()
                if not (0 <= x < h and 0 <= y < w) or visited[x][y] or grid[x][y] != color:
                    continue
                visited[x][y] = True
                component.append((x, y))
                q.extend([(x+1,y), (x-1,y), (x,y+1), (x,y-1)])

            if component:
                components.append((color, component))
    return components
def merger_merged(test_in):
    background = find_most_frequent_digit(test_in)
    blocks = extract_blocks_after_removing_background(test_in, background)
    return blocks
    
def extract_object_patch(input_grid):
    arr = np.array(input_grid)
    ys, xs = np.where(arr != 0)
    
    if len(ys) == 0:
        return [[0]*3 for _ in range(3)]  # fallback for empty grids
    
    min_y, max_y = ys.min(), ys.max()
    min_x, max_x = xs.min(), xs.max()
    
    # Try extracting 3x3 patch from bottom-left of object
    y_start = max_y - 2
    x_start = min_x

    # Clip bounds to avoid overflow
    y_start = max(0, min(y_start, arr.shape[0] - 3))
    x_start = max(0, min(x_start, arr.shape[1] - 3))

    patch = arr[y_start:y_start+3, x_start:x_start+3]
    return patch.tolist()

def shifted_pattern_match(grid, target):
    grid = np.array(grid)
    target = np.array(target)

    if grid.ndim != 2 or target.ndim != 2:
        return None  # or raise error, depends on your data expectations

    rows, cols = grid.shape
    t_rows, t_cols = target.shape

    if (rows, cols) != (t_rows, t_cols):
        return None

    # Try shifts in range -rows+1 to rows-1 (vertical shifts)
    # and -cols+1 to cols-1 (horizontal shifts)
    for dr in range(-rows + 1, rows):
        for dc in range(-cols + 1, cols):
            # Create empty grid filled with a special value (e.g. -1)
            shifted = np.full_like(grid, fill_value=-1)

            # Compute overlapping slice indices
            r1_start = max(0, dr)
            r1_end = min(rows, rows + dr)
            c1_start = max(0, dc)
            c1_end = min(cols, cols + dc)

            r2_start = max(0, -dr)
            r2_end = min(rows, rows - dr)
            c2_start = max(0, -dc)
            c2_end = min(cols, cols - dc)

            # Place shifted values accordingly
            shifted[r1_start:r1_end, c1_start:c1_end] = grid[r2_start:r2_end, c2_start:c2_end]

            # Check if shifted matches target exactly where defined
            # For cells where shifted == -1, ignore comparison (partial overlap)
            mask = shifted != -1
            if np.array_equal(shifted[mask], target[mask]):
                # Return shifted grid with -1 replaced by 0 or background color
                shifted[shifted == -1] = 0
                return shifted.tolist()

    # No shift match found
    return None

def hash_tile(tile):
    """Converts a tile (2D list) into a hashable form."""
    return tuple(tuple(row) for row in tile)

def extract_tile_mapping_rule(input_grid, output_grid):
    try:
        in_rows, in_cols = len(input_grid), len(input_grid[0])
        out_rows, out_cols = len(output_grid), len(output_grid[0])

        if out_rows % in_rows != 0 or out_cols % in_cols != 0:
            return None

        tile_height = out_rows // in_rows
        tile_width = out_cols // in_cols

        tile_map = {}
        seen_tiles = {}

        for i in range(in_rows):
            for j in range(in_cols):
                color = input_grid[i][j]
                tile = [
                    row[j * tile_width : (j + 1) * tile_width]
                    for row in output_grid[i * tile_height : (i + 1) * tile_height]
                ]
                tile_hashed = hash_tile(tile)

                # Check for color reuse with inconsistent tiles
                if color in tile_map:
                    if hash_tile(tile_map[color]) != tile_hashed:
                        return None  # Inconsistent tile for same color
                else:
                    tile_map[color] = tile

                # Check for tile reuse across multiple colors (not necessarily wrong, but record it)
                if tile_hashed in seen_tiles and seen_tiles[tile_hashed] != color:
                    # Optional: allow multiple colors mapping to same tile
                    continue
                seen_tiles[tile_hashed] = color

        # Try reconstruction and verify
        recon = apply_tile_mapping_rule(input_grid, {"tile_map": tile_map})
        if np.array_equal(np.array(recon), np.array(output_grid)):
            return {
                "type": "tile_mapping",
                "tile_map": tile_map,
                "tile_size": (tile_height, tile_width),
            }
    except:
        pass

    return None

def allignment(test_in):
    # Step 1: Fill patterns with middle digit
    filled_grid = fill_patterns_with_middle_digit(test_in)
    
    # Step 2: Extract patterns in order
    patterns = find_patterns_with_column_order(filled_grid)
    
    # Step 3: Split each pattern into compact grid
    split_grids = split_patterns(filled_grid, patterns)
    
    # Step 4: Store each pattern in separate variable
    pattern_vars = {f'pattern{idx + 1}': gg for idx, gg in enumerate(split_grids)}
    
    all_patterns = list(pattern_vars.values())
    aligned_patterns = align_patterns(all_patterns)
    
    # Align patterns using your final alignment logic
    aligned_patterns = align_patterns(list(pattern_vars.values()))
    
    # Join the aligned patterns
    final_grid = join_patterns(aligned_patterns)
    return final_grid
def apply_tile_mapping_rule(test_input, rule):
    tile_map = rule.get("tile_map", {})
    if not tile_map:
        return test_input

    in_rows, in_cols = len(test_input), len(test_input[0])
    tile_height = len(next(iter(tile_map.values())))
    tile_width = len(next(iter(tile_map.values()))[0])

    out_grid = [
        [0] * (in_cols * tile_width)
        for _ in range(in_rows * tile_height)
    ]

    for i in range(in_rows):
        for j in range(in_cols):
            color = test_input[i][j]
            tile = tile_map.get(color, [[0] * tile_width for _ in range(tile_height)])
            for di in range(tile_height):
                for dj in range(tile_width):
                    out_grid[i * tile_height + di][j * tile_width + dj] = tile[di][dj]

    return out_grid
    
def apply_template(input_grid, template):
    if not isinstance(template, list) or not isinstance(template[0], list):
        raise ValueError("Template should be a 2D list")

    output = [row[:] for row in input_grid]  # Deep copy
    for i in range(len(template)):
        for j in range(len(template[0])):
            if template[i][j] != -1:  # Use -1 for "ignore"
                output[i][j] = template[i][j]
    return output

def generate_concentric_pattern(grid):
    """
    Generate a concentric square pattern based on the input grid.
    Returns the modified grid if a concentric pattern is detected/generated,
    or None if no such pattern is detected.
    
    Args:
        grid: 2D list or numpy array representing the input grid.
    
    Returns:
        2D list (or numpy array) with concentric squares pattern, or None.
    """
    grid = np.array(grid)
    rows, cols = grid.shape
    if rows != cols:
        # Concentric squares need a square grid
        return None
    
    n = rows
    # Copy the grid to modify
    result = np.zeros_like(grid)
    
    # Find unique colors excluding background (assuming 0 is background)
    colors = [c for c in np.unique(grid) if c != 0]
    if not colors:
        return None
    
    # Sort colors by frequency descending (to assign outer layers)
    unique_colors_freq = sorted([(c, np.sum(grid == c)) for c in colors], key=lambda x: -x[1])
    sorted_colors = [c for c, _ in unique_colors_freq]
    
    # Number of layers = ceil(n/2)
    layers = (n + 1) // 2
    
    # Assign colors to layers cycling through available colors if needed
    for layer in range(layers):
        color = sorted_colors[layer % len(sorted_colors)]
        # Top row
        result[layer, layer:cols-layer] = color
        # Bottom row
        result[rows-layer-1, layer:cols-layer] = color
        # Left column
        result[layer:rows-layer, layer] = color
        # Right column
        result[layer:rows-layer, cols-layer-1] = color
    
    # If original center is different, keep original center value
    if n % 2 == 1:
        center = n // 2
        result[center, center] = grid[center, center]
    
    # Return as list of lists to be consistent with ARC format
    return result.tolist()

def extract_template_from_input_output(input_grid, output_grid):
    """
    Advanced template extraction: detects pixel-wise, color-wise, and structural changes.
    Returns a template grid that highlights what needs to be changed.
    """
    input_arr = np.array(input_grid)
    output_arr = np.array(output_grid)

    if input_arr.shape != output_arr.shape:
        return None  # For now, same-size only
    
    h, w = input_arr.shape
    template = np.full((h, w), -1)  # -1 means "unchanged"

    # Difference mask (value changed or added/removed)
    diff_mask = input_arr != output_arr
    changed_positions = np.argwhere(diff_mask)

    if not changed_positions.any():
        return None  # No difference

    # Strategy 1: Direct changes â†’ replace with output value
    for y, x in changed_positions:
        template[y, x] = output_arr[y, x]

    # Strategy 2: Identify if it's just a color change of same shapes
    unique_input_vals = np.unique(input_arr)
    unique_output_vals = np.unique(output_arr)
    if len(unique_input_vals) == len(unique_output_vals):
        # Try to guess color mapping
        color_map = {}
        for vin in unique_input_vals:
            for vout in unique_output_vals:
                if np.sum((input_arr == vin) & (output_arr == vout)) > 0:
                    color_map[vin] = vout
        # Reconstruct expected output with this mapping
        reconstructed = np.vectorize(lambda v: color_map.get(v, v))(input_arr)
        if np.array_equal(reconstructed, output_arr):
            return {"type": "color_map", "map": color_map}

    # Strategy 3: Detect translation of objects (same shape, different location)
    # Optional: Use object segmentation and compare position shifts

    return template.tolist()



def extract_rule(ins, outs, metas):
    rule = defaultdict(lambda: False)

    ins = sanitize_grids(ins)
    outs = sanitize_grids(outs)

    if any(m.get("areaOut", 0) < m.get("areaIn", 0) for m in metas):
        rule["shrink"] = True

    if ins and outs and ins[0] and outs[0]:
        cm = get_color_mapping(ins[0], outs[0])
        if any(k != v for k, v in cm.items()):
            rule["color_mapping"] = cm

    for d in ["up", "down", "left", "right"]:
        try:
            if all(safe_compare(shift_grid(i, d), o) for i, o in zip(ins, outs)):
                rule["shift"] = d
        except Exception:
            continue

    try:
        pattern, replacement = generalize_patterns(ins, outs)
        if pattern is not None and replacement is not None:
            if is_pattern_consistent(ins, outs, pattern, replacement):
                rule["pattern"] = pattern
                rule["replacement"] = replacement
    except Exception:
        pass

    try:
        scale_factors = fit_scaling_rule(ins, outs)
        if scale_factors:
            rule["scale_h"], rule["bias_h"] = scale_factors[0]
            rule["scale_w"], rule["bias_w"] = scale_factors[1]
    except Exception:
        pass

    try:
        for input_grid, output_grid in zip(ins, outs):
            objects_in = get_objects(input_grid)
            objects_out = get_objects(output_grid)
            relations = detect_object_relations(objects_in)
            if relations:
                rule["object_relations"] = relations
                break
    except Exception:
        pass

    try:
        for axis in ["vertical", "horizontal"]:
            if ins and outs and safe_compare(make_symmetric(ins[0], axis), outs[0]):
                rule["symmetric"] = axis
                break
    except Exception:
        pass

    for k, f in TRANSFORMS.items():
        try:
            if all(safe_compare(f(i), o) for i, o in zip(ins, outs)):
                rule[k] = True
        except Exception:
            pass

    # âœ… Add repeat_flip rule
    try:
        for inp, out in zip(ins, outs):
            repeat_flip_rule = extract_repeat_flip_rule(inp, out)
            if repeat_flip_rule:
                print("âœ… repeat_flip rule triggered")
                rule.update(repeat_flip_rule)
                break
    except Exception as e:
        print(f"â�Œ repeat_flip rule extraction error: {e}")

    return rule

def cropping_fol(test_in):
    components = extract_connected_components(test_in, bg_color=0)
            
    for color, pixels in components:
        # Build isolated component grid
        h, w = len(test_in), len(test_in[0])
        component_grid = [[0]*w for _ in range(h)]
        for y, x in pixels:
            component_grid[y][x] = color

        arr = np.array(component_grid)
        ys, xs = np.where(arr != 0)
        if len(ys) == 0:
            continue

        min_y, max_y = ys.min(), ys.max() + 1
        min_x, max_x = xs.min(), xs.max() + 1
        cropped = arr[min_y:max_y, min_x:max_x].tolist()
        return cropped
        
def apply_rule(grid, rule=None, max_steps=1):
    if grid is None:
        return []

    arr = to_np_array(grid)
    results = set()
    outputs = []

    try:
        if rule:
            arr_copy = copy.deepcopy(arr)

            # Pattern transform
            pattern = rule.get("pattern", None)
            replacement = rule.get("replacement", None)
            if pattern is not None and replacement is not None:
                try:
                    arr_copy_list = arr_copy.tolist()
                    arr_copy_list = apply_pattern_transformation(arr_copy_list, pattern, replacement)
                    if all(len(row) == len(arr_copy_list[0]) for row in arr_copy_list):
                        arr_copy = np.array(arr_copy_list)
                    else:
                        arr_copy = np.array(grid)
                except:
                    arr_copy = np.array(grid)

            # Object relations (optional: not implemented)
            if "object_relations" in rule:
                pass  # implement if needed

            # Symmetry
            if "symmetric" in rule:
                try:
                    sym_arr = make_symmetric(arr_copy.tolist(), rule["symmetric"])
                    arr_copy = to_np_array(sym_arr)
                except:
                    pass

            # Base transforms
            for key in rule:
                if key in BASE_TRANSFORMS:
                    transform_fn = BASE_TRANSFORMS[key]
                    try:
                        if key in ["color_mapping", "shift", "scale_factor", "translate"]:
                            arr_copy = transform_fn(arr_copy, rule)
                        else:
                            arr_copy = transform_fn(arr_copy)
                    except:
                        pass

            # âœ… Apply repeat_flip if specified
            if rule.get("transform") == "repeat_flip":
                print("ğŸš€ Applying repeat_flip rule")
                try:
                    arr_copy = apply_repeat_flip_rule(arr_copy.tolist(), rule)
                except:
                    pass

            base_result = arr_copy.tolist()
            base_key = str(base_result)
            if base_key not in results:
                results.add(base_key)
                outputs.append(base_result)

    except:
        return []

    # Composed transforms
    compose_keys = [
        "flip_horizontal", "flip_vertical", "rotate_90", "rotate_180",
        "rotate_270", "transpose", "reflect_main_diag", "reflect_anti_diag",
        "invert_colors", "concentric_squares"
    ]
    COMPOSE_TRANSFORMS = {k: BASE_TRANSFORMS[k] for k in compose_keys if k in BASE_TRANSFORMS}

    for r in range(1, max_steps + 1):
        for ops in permutations(COMPOSE_TRANSFORMS.keys(), r):
            try:
                composed = to_np_array(grid)
                for op in ops:
                    composed = COMPOSE_TRANSFORMS[op](composed)
                composed_list = composed.tolist()
                key = str(composed_list)
                if key not in results:
                    results.add(key)
                    outputs.append(composed_list)
            except:
                continue

    return outputs
