def extract_object_rules(input_objs, output_objs, matches):
    rules = []
    for i_idx, o_idx in matches:
        i_obj = input_objs[i_idx]
        o_obj = output_objs[o_idx]

        # Detect translation
        trans = detect_translation(i_obj, o_obj)
        if trans:
            rule = {"transform": "translate", "dy": trans[0], "dx": trans[1]}
        else:
            # Fall back to normal rule extraction
            i_grid = i_obj['grid']
            o_grid = o_obj['grid']
            meta = {
                "areaIn": np.sum(np.array(i_grid) > 0),
                "areaOut": np.sum(np.array(o_grid) > 0)
            }
            rule = extract_rule([i_grid], [o_grid], [meta])

        rules.append((i_idx, rule))
    return rules
import numpy as np
from scipy.ndimage import label

def apply_object_rules(input_grid, input_objs, object_rules):
    h, w = np.array(input_grid).shape
    canvas = [[0 for _ in range(w)] for _ in range(h)]

    for idx, rule in object_rules:
        obj = input_objs[idx]
        r, c = obj['position']
        obj_grid = obj['grid']

        if rule.get("transform") == "translate":
            dy, dx = rule["dy"], rule["dx"]
            for i in range(len(obj_grid)):
                for j in range(len(obj_grid[0])):
                    val = obj_grid[i][j]
                    if val != 0:
                        new_r, new_c = r + dy + i, c + dx + j
                        if 0 <= new_r < h and 0 <= new_c < w:
                            canvas[new_r][new_c] = val
        else:
            # fallback to default rule
            transformed = apply_rule(obj_grid, rule, max_steps=2)
            if transformed:
                out_grid = transformed[0]
                for i in range(len(out_grid)):
                    for j in range(len(out_grid[0])):
                        if r + i < h and c + j < w:
                            canvas[r + i][c + j] = out_grid[i][j]
    return canvas

def center_objects(grid, bg_color=0):
    from copy import deepcopy
    objects = extract_connected_components(grid, bg_color)
    h, w = len(grid), len(grid[0])
    new_grid = [[bg_color]*w for _ in range(h)]

    for color, pixels in objects:
        min_y = min(y for y, x in pixels)
        min_x = min(x for y, x in pixels)
        norm = [(y - min_y, x - min_x) for y, x in pixels]
        obj_h = max(y for y, x in norm) + 1
        obj_w = max(x for y, x in norm) + 1

        off_y = (h - obj_h) // 2
        off_x = (w - obj_w) // 2

        for dy, dx in norm:
            new_grid[off_y + dy][off_x + dx] = color

    return new_grid

