def count_objects_by_color(grid):
    """
    Counts the number of objects for each color in the grid.
    
    Args:
        grid (list of list or np.array): Input grid with colors as integers.
    
    Returns:
        dict: {color: object_count}
    """
    grid_np = np.array(grid)
    colors = np.unique(grid_np)
    counts = {}
    for c in colors:
        if c == 0:  # skip background if 0
            continue
        mask = (grid_np == c)
        labeled, _ = label(mask)

        counts[c] = labeled.max()  # number of connected components (objects) of color c
    return counts

def count_connected_components_by_color(grid, bg_color=0):
    from collections import defaultdict, deque
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]
    counts = defaultdict(int)

    for i in range(h):
        for j in range(w):
            if visited[i][j] or grid[i][j] == bg_color:
                continue
            color = grid[i][j]
            q = deque([(i, j)])
            while q:
                x, y = q.popleft()
                if not (0 <= x < h and 0 <= y < w) or visited[x][y] or grid[x][y] != color:
                    continue
                visited[x][y] = True
                q.extend([(x+1,y), (x-1,y), (x,y+1), (x,y-1)])
            counts[color] += 1
    return dict(counts)

