def extract_meta_features(grid_in, grid_out):
    features = {}

    # Example meta features you mentioned before (you can expand this)
    features["SameSizeInOut"] = (np.array(grid_in).shape == np.array(grid_out).shape)
    features["widthIn"] = np.array(grid_in).shape[1]
    features["widthOut"] = np.array(grid_out).shape[1]
    features["highIn"] = np.array(grid_in).shape[0]
    features["highOut"] = np.array(grid_out).shape[0]
    features["areaIn"] = features["widthIn"] * features["highIn"]
    features["areaOut"] = features["widthOut"] * features["highOut"]

    # For colors
    colors_in = set(np.unique(grid_in))
    colors_out = set(np.unique(grid_out))
    features["SameColorsInOut"] = (colors_in == colors_out)
    features["SameColorsIn"] = (len(colors_in) == len(colors_in))
    features["SameColorsOut"] = (len(colors_out) == len(colors_out))

    # Object counts per color
    features["count_objects_in"] = count_objects_by_color(grid_in)
    features["count_objects_out"] = count_objects_by_color(grid_out)

    return features

