def compare(pred, exp):
    exp_grid = parse_grid(exp)
    
    # --- Error Suppression Block ---
    try:
        
        if np.shape(pred) != np.shape(exp_grid):
            return False
            
        # If the shapes match, perform the array equality check
        return np.array_equal(np.array(pred), np.array(exp_grid))

    except ValueError:
        
        return False

