def get_nonzero_position_label(grid3x3):
    labels = ['a', 'b', 'c',
              'd', 'e', 'f',
              'g', 'h', 'i']
    
    for i in range(3):
        for j in range(3):
            if grid3x3[i][j] != 0:
                return labels[i * 3 + j]
    
    return None  # If all cells are zero

def place_block_in_9x9(s, label):
    label_to_position = {
        'a': (0, 0), 'b': (0, 3), 'c': (0, 6),
        'd': (3, 0), 'e': (3, 3), 'f': (3, 6),
        'g': (6, 0), 'h': (6, 3), 'i': (6, 6)
    }

    if label not in label_to_position:
        raise ValueError("Label must be one of: 'a' to 'i'.")

    grid9 = [[0 for _ in range(9)] for _ in range(9)]
    start_i, start_j = label_to_position[label]

    for i in range(3):
        for j in range(3):
            grid9[start_i + i][start_j + j] = s[i][j]

    return grid9

def extract_matching_region(new_grid, filled_grid):
    # Find position of non-zero value in new_grid
    for i in range(len(new_grid)):
        for j in range(len(new_grid[0])):
            if new_grid[i][j] != 0:
                nz_row, nz_col = i, j
                break

    # Find corresponding position in filled_grid (13,13)
    filled_nz_row, filled_nz_col = 12, 12

    # Calculate top-left corner in filled_grid that aligns with new_grid
    top_left_row = filled_nz_row - nz_row
    top_left_col = filled_nz_col - nz_col

    # Extract the region from filled_grid
    h, w = len(new_grid), len(new_grid[0])
    result = [row[top_left_col:top_left_col + w] for row in filled_grid[top_left_row:top_left_row + h]]
    return result
    
