def extract_digit_pairs(blocks):
    pairs = []
    for block in blocks:
        digits = set()
        for row in block:
            digits.update(d for d in row if d != 0)
        if len(digits) != 2:
            raise ValueError(f"Block must have exactly two digits (excluding 0), got {digits}")
        # Sort so we always take smaller as new_digit, larger as old_digit
        new_digit, old_digit = sorted(digits)
        pairs.append((new_digit, old_digit))
    return pairs

def replace_old_with_new(rest_blocks, large_block):
    # Extract pairs
    pairs = extract_digit_pairs(rest_blocks)
    
    # Build mapping: old_digit -> new_digit
    replace_map = {old: new for new, old in pairs}
    
    replaced_block = []
    for row in large_block:
        new_row = []
        for cell in row:
            if cell in replace_map:
                new_row.append(replace_map[cell])
            else:
                new_row.append(cell)
        replaced_block.append(new_row)
    return replaced_block

