from collections import Counter
import numpy as np

def count_digit_blocks(components: List[Any]) -> Dict[int, int]:
    """
    Counts the number of components containing each unique non-zero digit.
    Works even if 'components' are dicts with 'grid' keys or raw numpy arrays.
    """
    cnt = Counter()
    for comp in components:
        # Handle both dict and ndarray
        if isinstance(comp, dict):
            grid = np.array(comp.get('grid', []))
        else:
            grid = np.array(comp)
        
        if grid.size == 0:
            continue
        
        # Collect unique nonzero digits in this component
        digits_in_comp = set(int(val) for val in grid.flatten() if val != 0)
        
        # Increment one count per digit present in this component
        for d in digits_in_comp:
            cnt[d] += 1

    return dict(cnt)


from typing import List, Dict, Any, Optional

def make_fixed_m_by_5_from_components(
    components: List[Dict[str, Any]],
    digit_to_col: Optional[Dict[int,int]] = None,
    bottom_up: bool = True
) -> List[List[int]]:
    
    if digit_to_col is None:
        digit_to_col = {5:0, 2:1, 8:2, 9:3, 6:4}

    counts = count_digit_blocks(components)   # use your function exactly as requested
    if not counts:
        return []

    m = max(counts.values())
    cols = 5
    out = [[0]*cols for _ in range(m)]

    for digit, col in digit_to_col.items():
        if not (0 <= col < cols):
            raise ValueError(f"Invalid column for digit {digit}: {col}")
        cnt = counts.get(digit, 0)
        if cnt <= 0:
            continue
        if bottom_up:
            start = m - cnt
            for r in range(start, m):
                out[r][col] = digit
        else:
            for r in range(0, cnt):
                out[r][col] = digit

    return out

from typing import List

def compress_border_around_inner_3x3(grid: List[List[int]], strategy: str = "auto") -> List[List[int]]:
   
    if grid is None or len(grid) == 0:

        return []

    H = len(grid)
    W = len(grid[0])

    # --- compress columns ---
    if W > 5:
        mid_c = W // 2
        cols_idx = [0, max(0, mid_c - 1), mid_c, min(W - 1, mid_c + 1), W - 1]
        # keep order and uniqueness (usually already unique and ordered)
        seen = []
        cols_idx_unique = []
        for c in cols_idx:
            if c not in seen:
                seen.append(c)
                cols_idx_unique.append(c)
        cols_idx = cols_idx_unique
    else:
        cols_idx = list(range(W))

    # build intermediate grid with selected columns
    intermediate = [[row[c] for c in cols_idx] for row in grid]
    H2 = len(intermediate)
    W2 = len(intermediate[0]) if H2 > 0 else 0

    # If height already <= 5, we won't remove rows (just return rows but ensure at most 5 by strategy?)
    # User examples always start with H=6 and want H=5; implement removal only when H2 > 5.
    if H2 <= 5:
        return intermediate

    def remove_index_from_inter(i: int) -> List[List[int]]:
        return [row[:] for idx, row in enumerate(intermediate) if idx != i]

    # quick strategies
    if strategy == "top":
        return remove_index_from_inter(0)
    if strategy == "bottom":
        return remove_index_from_inter(H2 - 1)

    # auto: try symmetry (top == bottom) first
    if strategy == "auto":
        symmetric_candidates = []
        for i in range(H2):
            new = remove_index_from_inter(i)
            if new[0] == new[-1]:
                symmetric_candidates.append(i)
        if symmetric_candidates:
            best_i = min(symmetric_candidates)
            return remove_index_from_inter(best_i)
        # else fall through to scoring

    # scoring heuristic: maximize non-border cells in central 3-row window
    best_score = -1
    best_i = None
    best_new = None
    for i in range(H2):
        new = remove_index_from_inter(i)
        nH = len(new)
        # determine central 3-row window in 'new'
        if nH <= 3:
            r0 = 0
            r1 = nH - 1
        else:
            mid = nH // 2
            r0 = max(0, mid - 1)
            r1 = min(nH - 1, mid + 1)
        border_val = new[0][0]
        score = 0
        for rr in range(r0, r1 + 1):
            for cc in range(W2):
                if new[rr][cc] != border_val:
                    score += 1
        if score > best_score or (score == best_score and (best_i is None or i < best_i)):
            best_score = score
            best_i = i
            best_new = new

    return best_new

from typing import List, Tuple

def place_blocks_on_bg(
    H: int,
    W: int,
    block: List[List[int]],
    positions: List[Tuple[int,int]],
    bg: int = 7
) -> List[List[int]]:
   
    # create background
    out = [[bg for _ in range(W)] for _ in range(H)]
    bh = len(block)
    bw = len(block[0]) if bh>0 else 0

    for (r0, c0) in positions:
        for i in range(bh):
            for j in range(bw):
                r = r0 + i
                c = c0 + j
                if 0 <= r < H and 0 <= c < W:
                    out[r][c] = block[i][j]
    return out

def copy_block_to15(grid):
    positions = [(2, 2), (8, 8)]
    gg = compress_border_around_inner_3x3(grid)
    grid15 = place_blocks_on_bg(15, 15, gg, positions, bg=7)
    return grid15

def stack_accordingly(grid):
    dom = get_dominant_digit(grid)
    gg = replace_digit_with_zero(grid,dom)
    comps = extract_8_connected_components(gg)
    counts = count_digit_blocks(comps)
    out = make_fixed_m_by_5_from_components(comps)
    return fill_zeros_with_dominant(out,dom)

