                    avg_ratio = sum(all_ratios) / len(all_ratios) if all_ratios else 1

                    def repeat_grid(grid, axis, color_map, ratio):
                        from math import ceil
                        mapped = [[color_map.get(cell, cell) for cell in row] for row in grid]
                        h, w = len(mapped), len(mapped[0])
                        if axis == "row":
                            out_h = ceil(h * ratio)
                            full, rem = divmod(out_h, h)
                            return mapped * full + mapped[:rem]
                        elif axis == "col":
                            out_w = ceil(w * ratio)
                            full, rem = divmod(out_w, w)
                            return [row * full + row[:rem] for row in mapped]
                        return mapped

