    # ğŸ’¾ Build and save ARC submission in the exact required schema (No [[0]] version)
    import json, numpy as np, os

    def normalize_grid(g):
        """Ensure grid is valid: list[list[int]] with 0â€“9 only."""
        if g is None:
            return None
        if isinstance(g, np.ndarray):
            g = g.tolist()
        # Flatten overly nested lists [[[...]]] â†’ [[...]]
        while isinstance(g, list) and len(g) == 1 and isinstance(g[0], list):
            g = g[0]
        if not g or not all(isinstance(r, list) for r in g):
            return None
        try:
            g = [[int(max(0, min(9, int(float(x))))) for x in r] for r in g if r]
        except Exception:
            return None
        if not g or not all(g) or any(len(r) != len(g[0]) for r in g):
            return None
        return g
    
    def flatten_if_nested(g):
        while isinstance(g, list) and len(g) == 1 and isinstance(g[0], list):
            g = g[0]
        return g
    
    formatted_predictions = {}
    
    for tid, preds in predictions.items():
        # standardize container type
        if isinstance(preds, dict):
            preds = [preds]
        elif not isinstance(preds, list):
            preds = [preds]
    
        g1 = g2 = None
    
        for p in preds:
            if isinstance(p, dict):
                # direct attempt_1 / attempt_2 structure
                a1 = normalize_grid(p.get("attempt_1"))
                a2 = normalize_grid(p.get("attempt_2"))
                if a1 is not None and a2 is not None:
                    g1, g2 = flatten_if_nested(a1), flatten_if_nested(a2)
                    break
                elif a1 is not None:
                    g1 = g2 = flatten_if_nested(a1)
                    break
                elif a2 is not None:
                    g1 = g2 = flatten_if_nested(a2)
                    break
            elif isinstance(p, list):
                a = normalize_grid(p)
                if a is not None:
                    g1 = g2 = flatten_if_nested(a)
                    break
    
        # only keep valid grids
        if g1 is not None and g2 is not None:
            formatted_predictions[tid] = [{"attempt_1": g1, "attempt_2": g2}]
        else:
            # fallback empty safe grid
            formatted_predictions[tid] = [{"attempt_1": [[0]], "attempt_2": [[0]]}]
    
    def force_pure_python(obj):
        """Recursively convert numpy types â†’ native Python types."""
        if isinstance(obj, dict):
            return {str(k): force_pure_python(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [force_pure_python(v) for v in obj]
        if isinstance(obj, (np.integer,)):
            return int(obj)
        if isinstance(obj, (np.floating,)):
            return int(round(float(obj)))
        if isinstance(obj, (np.bool_,)):
            return bool(obj)
        return obj
    
    formatted_predictions = force_pure_python(formatted_predictions)
    
    # --- Validate ---
    for tid, lst in formatted_predictions.items():
        assert isinstance(lst, list) and len(lst) >= 1, f"{tid}: must have â‰¥1 predictions"
        for d in lst:
            assert isinstance(d, dict), f"{tid}: must contain dict"
            for k in ("attempt_1", "attempt_2"):
                g = d[k]
                assert isinstance(g, list), f"{tid}: {k} must be list"
                assert all(isinstance(r, list) for r in g), f"{tid}: {k} bad rows"
                assert all(isinstance(x, int) and 0 <= x <= 9 for r in g for x in r), f"{tid}: {k} invalid values"
    
    # --- Save submission ---
    submission_path = "/kaggle/working/submission.json"
