    import os, json, numpy as np

    current_predictions_to_save = {}
    
    def clean_grid(g):
        if isinstance(g, np.ndarray):
            g = g.tolist()
        while isinstance(g, list) and len(g) == 1 and isinstance(g[0], list):
            g = g[0]
        if not g or not all(isinstance(r, (list, tuple)) and r for r in g):
            return None
        cleaned = []
        for r in g:
            row = []
            for x in r:
                try:
                    val = int(max(0, min(9, int(float(x)))))
                except Exception:
                    val = 0
                row.append(val)
            cleaned.append(row)
        w = len(cleaned[0])
        cleaned = [r[:w] for r in cleaned if len(r) >= w]
        return cleaned
    
    def make_fallback_output(input_grid):
        if isinstance(input_grid, np.ndarray):
            input_grid = input_grid.tolist()
        if not input_grid:
            return [[0]]
        h, w = len(input_grid), len(input_grid[0])
        return [[0 for _ in range(w)] for _ in range(h)]
    
    for tid, preds in predictions.items():
        g1 = g2 = None
        if not isinstance(preds, list):
            preds = [preds]
        for p in preds:
            try:
                if isinstance(p, dict) and "attempt_1" in p and "attempt_2" in p:
                    a1, a2 = clean_grid(p["attempt_1"]), clean_grid(p["attempt_2"])
                    if a1 is not None and a2 is not None:
                        g1, g2 = a1, a2
                        break
                elif isinstance(p, list):
                    a = clean_grid(p)
                    if a is not None:
                        g1 = g2 = a
                        break
            except Exception:
                continue
        if g1 is None or g2 is None:
            try:
                sample_in = parse_grid(df[df["task_id"] == tid].iloc[0]["input"])
            except Exception:
                sample_in = [[0]]
            g1 = g2 = make_fallback_output(sample_in)
        current_predictions_to_save[tid] = [{"attempt_1": g1, "attempt_2": g2}]
    
    expected_predict_tasks = df[df["type"] == "predict"]["task_id"].unique().tolist()
    for tid in expected_predict_tasks:
        if tid not in current_predictions_to_save:
            try:
                sample_in = parse_grid(df[df["task_id"] == tid].iloc[0]["input"])
            except Exception:
                sample_in = [[0]]
            g = make_fallback_output(sample_in)
            current_predictions_to_save[tid] = [{"attempt_1": g, "attempt_2": g}]
    
    submission_path = "/kaggle/working/submission.json"
    existing_submissions = {}
    
    if os.path.exists(submission_path):
        with open(submission_path, "r") as f:
            try:
                existing_submissions = json.load(f)
            except json.JSONDecodeError:
                existing_submissions = {}
    
    def force_pure_python(obj):
        if isinstance(obj, dict):
            return {k: force_pure_python(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [force_pure_python(v) for v in obj]
        elif isinstance(obj, tuple):
            return [force_pure_python(v) for v in obj]
        elif isinstance(obj, np.ndarray):
            return force_pure_python(obj.tolist())
        elif isinstance(obj, (np.integer,)):
            return int(obj)
        elif isinstance(obj, (np.floating,)):
            return int(round(float(obj)))
        return obj
    
    def deep_validate(submissions):
        bad = []
        for tid, preds in list(submissions.items()):
            try:
                if not isinstance(preds, list) or len(preds) != 1:
                    raise ValueError("must be single-element list")
                d = preds[0]
                if not isinstance(d, dict) or "attempt_1" not in d or "attempt_2" not in d:
                    raise ValueError("missing attempt keys")
                for att in ["attempt_1", "attempt_2"]:
                    g = d[att]
                    if not isinstance(g, list) or not g or not all(isinstance(r, list) for r in g):
                        raise ValueError(f"{att} malformed grid")
                    w = len(g[0])
                    if any(len(r) != w for r in g):
                        raise ValueError(f"{att} uneven rows")
                    for r in g:
                        for x in r:
                            if not isinstance(x, int) or not (0 <= x <= 9):
                                raise ValueError(f"{att} invalid value {x}")
            except Exception as e:
                bad.append((tid, str(e)))
                del submissions[tid]
        if bad:
            print(f"âš ï¸� Removed {len(bad)} invalid tasks:")
            for tid, msg in bad[:8]:
                print(f"   - {tid}: {msg}")
    
    try:
        existing_submissions.update(current_predictions_to_save)
        existing_submissions = force_pure_python(existing_submissions)
    
        # Ensure one prediction per task
        for tid, lst in list(existing_submissions.items()):
            if isinstance(lst, list) and len(lst) > 1:
                existing_submissions[tid] = [lst[-1]]
    
        deep_validate(existing_submissions)
    
        with open(submission_path, "w") as f:
            json.dump(existing_submissions, f, separators=(",", ":"))
    
        print(f"ğŸ§© Total tasks written: {len(existing_submissions)}")
        if 'solved' in locals() and 'reward' in locals():
            print(f"ğŸ�† Solved: {len(solved)} / {df['task_id'].nunique()}, Reward: {reward}")
    
    except Exception as e:
        print(f"âš ï¸� Submission save failed: {e}")
    
    try:
        return reward, solved, unsolved, current_predictions_to_save
    except Exception:
        pass




